  'messages' => 
  array (
    'PhishTank list downloaded: %d entries.' => 'PhishTank பட்டியல் பதிவிறக்கப்பட்டது: %d உள்ளீடுகள்.',
    'The PhishTank list could not be downloaded (%s). Links are not checked against it until it is.' => 'PhishTank பட்டியலைப் பதிவிறக்க முடியவில்லை (%s). பதிவிறக்கும் வரை இணைப்புகள் அதனுடன் சரிபார்க்கப்படாது.',
    'Phishing links are no longer checked.' => 'ஃபிஷிங் இணைப்புகள் இனி சரிபார்க்கப்படாது.',
    'Phishing links (PhishTank)' => 'ஃபிஷிங் இணைப்புகள் (PhishTank)',
    'Links in comments and contact forms are checked against PhishTank, the list of verified phishing pages that are still online, kept by Cisco Talos. The list is downloaded twice a day and checked on this server: nothing your visitors write is sent anywhere. A comment with a listed link goes to spam; a contact message with one is not delivered.' => 'கருத்துகள் மற்றும் தொடர்புப் படிவங்களில் உள்ள இணைப்புகள் PhishTank உடன் சரிபார்க்கப்படுகின்றன; இது இன்னும் இணையத்தில் உள்ள உறுதிசெய்யப்பட்ட ஃபிஷிங் பக்கங்களின் பட்டியல், Cisco Talos பராமரிக்கிறது. பட்டியல் நாளுக்கு இருமுறை பதிவிறக்கப்பட்டு இந்தச் சர்வரிலேயே பார்க்கப்படுகிறது: உங்கள் பார்வையாளர்கள் எழுதுவது எங்கும் அனுப்பப்படாது. பட்டியலிலுள்ள இணைப்புடன் உள்ள கருத்து ஸ்பாமுக்குச் செல்லும்; அத்தகைய இணைப்புடன் உள்ள தொடர்புச் செய்தி வழங்கப்படாது.',
    'PhishTank allows commercial and non-commercial use.' => 'PhishTank வணிக மற்றும் வணிகமற்ற பயன்பாட்டை அனுமதிக்கிறது.',
    'PhishTank FAQ' => 'PhishTank அடிக்கடி கேட்கப்படும் கேள்விகள்',
    'Without a key PhishTank allows only a few downloads a day from the same server. If the download fails, create a free account at phishtank.org and add your application key to wp-config.php:' => 'சாவி இல்லாமல், ஒரே சர்வரிலிருந்து நாளொன்றுக்குச் சில பதிவிறக்கங்களையே PhishTank அனுமதிக்கும். பதிவிறக்கம் தோல்வியுற்றால், phishtank.org இல் இலவசக் கணக்கு உருவாக்கி உங்கள் பயன்பாட்டுச் சாவியை wp-config.php இல் சேர்க்கவும்:',
    'The list has not changed since %s: PhishTank may have stopped updating it. Links are still checked against the last copy.' => 'பட்டியல் %s முதல் மாறவில்லை: PhishTank அதைப் புதுப்பிப்பதை நிறுத்தியிருக்கலாம். இணைப்புகள் இன்னும் கடைசி நகலுடன் சரிபார்க்கப்படுகின்றன.',
    'Check links in comments and contact forms against PhishTank' => 'கருத்துகள், தொடர்புப் படிவங்களின் இணைப்புகளை PhishTank உடன் சரிபார்',
    'by %1$s · %2$s · %3$s' => '%1$s · %2$s · %3$s வழங்கியது',
    'Firewall' => 'ஃபயர்வால்',
    'You are not allowed to do this.' => 'இதைச் செய்ய உங்களுக்கு அனுமதி இல்லை.',
    'Stops requests with the shape of an attack (database injection, reading server files, running code, scripts in links) and the scanners that look for weak spots. People who can edit the site are never inspected.' => 'தாக்குதல் வடிவிலான கோரிக்கைகளை (தரவுத்தளத்தில் ஊடுருவல், சர்வர் கோப்புகளைப் படித்தல், குறியீட்டை இயக்குதல், இணைப்புகளில் ஸ்கிரிப்ட்) மற்றும் பலவீனங்களைத் தேடும் ஸ்கேனர்களை நிறுத்துகிறது. தளத்தைத் திருத்தக்கூடியவர்கள் ஒருபோதும் சோதிக்கப்படுவதில்லை.',
    'Changes saved.' => 'மாற்றங்கள் சேமிக்கப்பட்டன.',
    'DRACO_WAF_OFF is set in wp-config.php: the firewall is off. Remove that line once the problem is fixed.' => 'wp-config.php-இல் DRACO_WAF_OFF அமைக்கப்பட்டுள்ளது: ஃபயர்வால் அணைக்கப்பட்டுள்ளது. பிரச்சினை சரியானதும் அந்த வரியை நீக்கவும்.',
    'Switch on the firewall' => 'ஃபயர்வாலை இயக்கு',
    'Log only: write down what it would stop, without stopping anything (start here for a few days)' => 'பதிவு மட்டும்: நிறுத்தக்கூடியதை எழுதிவைக்கும், எதையும் நிறுத்தாது (முதல் சில நாட்கள் இங்கிருந்து தொடங்குங்கள்)',
    'Block: stop those requests; five in 10 minutes put the address on the block list for 7 days' => 'தடு: அந்தக் கோரிக்கைகளை நிறுத்தும்; 10 நிமிடங்களில் ஐந்து முறை நடந்தால் அந்த முகவரி 7 நாட்களுக்குத் தடைப் பட்டியலில் சேரும்',
    'Hide the list of user names from anonymous visitors (?author=1 and /wp-json/wp/v2/users), the first step of password attacks' => 'அநாமதேயப் பார்வையாளர்களிடமிருந்து பயனர் பெயர்ப் பட்டியலை மறைக்கவும் (?author=1 மற்றும் /wp-json/wp/v2/users), கடவுச்சொல் தாக்குதல்களின் முதல் படி',
    'Limit failed logins: 10 in 10 minutes lock that address out of the login for 30 minutes' => 'தோல்வியுற்ற உள்நுழைவுகளைக் கட்டுப்படுத்து: 10 நிமிடங்களில் 10 முறை நடந்தால் அந்த முகவரி 30 நிமிடங்களுக்கு உள்நுழைய முடியாது',
    'Turn off XML-RPC completely (leave it on if you use Jetpack or the WordPress mobile app; its riskiest parts are always off)' => 'XML-RPC-ஐ முழுமையாக அணை (Jetpack அல்லது WordPress மொபைல் செயலியைப் பயன்படுத்தினால் இயக்கத்தில் வைக்கவும்; அதன் மிக ஆபத்தான பகுதிகள் எப்போதும் அணைக்கப்பட்டிருக்கும்)',
    'Save' => 'சேமி',
    'scanner tool' => 'ஸ்கேனர் கருவி',
    'looking for sensitive files' => 'முக்கியக் கோப்புகளைத் தேடுதல்',
    'database injection' => 'தரவுத்தள ஊடுருவல்',
    'reading server files' => 'சர்வர் கோப்புகளைப் படித்தல்',
    'running code' => 'குறியீட்டை இயக்குதல்',
    'script in the link' => 'இணைப்பில் ஸ்கிரிப்ட்',
    'many passwords in one XML-RPC call' => 'ஒரே XML-RPC அழைப்பில் பல கடவுச்சொற்கள்',
    'Recent attacks' => 'சமீபத்திய தாக்குதல்கள்',
    'Kept for 90 days. "Evidence" downloads everything from that address for an abuse report. In log-only mode they appear as "Would block".' => '90 நாட்கள் வைக்கப்படும். "சான்று" தவறான பயன்பாட்டு அறிக்கைக்காக அந்த முகவரியின் அனைத்தையும் பதிவிறக்கும். பதிவு மட்டும் முறையில் இவை "தடுத்திருக்கும்" எனக் காட்டப்படும்.',
    'Date (UTC)' => 'தேதி (UTC)',
    'What' => 'என்ன',
    'Address requested' => 'கோரப்பட்ட முகவரி',
    'Result' => 'முடிவு',
    'Blocked' => 'தடுக்கப்பட்டது',
    'Would block' => 'தடுத்திருக்கும்',
    'Evidence' => 'சான்று',
    'No attacks seen yet.' => 'இன்னும் எந்தத் தாக்குதலும் காணப்படவில்லை.',
    'The firewall is off.' => 'ஃபயர்வால் அணைக்கப்பட்டுள்ளது.',
    'If the firewall ever blocks you, add define(\'DRACO_WAF_OFF\', true); to wp-config.php, log in, look at this list and remove the line.' => 'ஃபயர்வால் உங்களையே தடுத்தால், wp-config.php-இல் define(\'DRACO_WAF_OFF\', true); சேர்த்து, உள்நுழைந்து, இந்தப் பட்டியலைப் பார்த்து, அந்த வரியை நீக்கவும்.',
    'Firewall: %d attacks in 10 minutes' => 'ஃபயர்வால்: 10 நிமிடங்களில் %d தாக்குதல்கள்',
    'Request blocked' => 'கோரிக்கை தடுக்கப்பட்டது',
    'This request was stopped for security reasons. If you think this is a mistake, contact the owner of the site.' => 'பாதுகாப்புக் காரணங்களுக்காக இந்தக் கோரிக்கை நிறுத்தப்பட்டது. இது தவறு என நினைத்தால், தள உரிமையாளரைத் தொடர்பு கொள்ளவும்.',
    'Too many failed logins from your address. Try again in 30 minutes.' => 'உங்கள் முகவரியிலிருந்து அதிகமான தோல்வியுற்ற உள்நுழைவுகள். 30 நிமிடங்களில் மீண்டும் முயலவும்.',
    'Forms and sign-ups' => 'படிவங்களும் பதிவுகளும்',
    'From the list of submissions (#%d)' => 'அனுப்பியவற்றின் பட்டியலிலிருந்து (#%d)',
    'Holds every contact message, comment and new account until the sender confirms from their e-mail. Bots do not confirm, so their spam never reaches you. Payments in the shop are never held.' => 'அனுப்புநர் தன் மின்னஞ்சலிலிருந்து உறுதிப்படுத்தும் வரை ஒவ்வொரு தொடர்புச் செய்தி, கருத்து மற்றும் புதிய கணக்கையும் நிறுத்திவைக்கிறது. பாட்கள் உறுதிப்படுத்துவதில்லை, எனவே அவற்றின் ஸ்பேம் உங்களை ஒருபோதும் சேராது. கடையில் செய்யும் கட்டணங்கள் ஒருபோதும் நிறுத்தப்படுவதில்லை.',
    'Nothing was blocked: the value is not valid, belongs to an administrator, or is your own address.' => 'எதுவும் தடுக்கப்படவில்லை: மதிப்பு செல்லாது, ஒரு நிர்வாகிக்குச் சொந்தமானது, அல்லது உங்கள் சொந்த முகவரி.',
    'It is on without SMTP. If the confirmation mail does not arrive, messages are deleted after 48 hours without anyone knowing.' => 'SMTP இல்லாமல் இயக்கத்தில் உள்ளது. உறுதிப்படுத்தல் மின்னஞ்சல் வராவிட்டால், செய்திகள் 48 மணி நேரத்தில் யாருக்கும் தெரியாமல் நீக்கப்படும்.',
    'Set up Site mail (SMTP) →' => 'தள மின்னஞ்சலை (SMTP) அமை →',
    'Block this sender?' => 'இந்த அனுப்புநரைத் தடுக்கவா?',
    'Also block the IP address' => 'IP முகவரியையும் தடு',
    '%d days' => '%d நாட்கள்',
    'Block' => 'தடு',
    'Settings' => 'அமைப்புகள்',
    'Verify contact forms and sign-ups' => 'தொடர்புப் படிவங்களையும் பதிவுகளையும் சரிபார்',
    'Include new user accounts (accounts created while paying in the shop are never held)' => 'புதிய பயனர் கணக்குகளையும் சேர் (கடையில் பணம் செலுத்தும்போது உருவாகும் கணக்குகள் ஒருபோதும் நிறுத்தப்படுவதில்லை)',
    'Include blog comments: they are not saved, not even as pending, until the author confirms. Trackbacks and pingbacks are dropped.' => 'வலைப்பதிவுக் கருத்துகளையும் சேர்: ஆசிரியர் உறுதிப்படுத்தும் வரை நிலுவையாகக்கூடச் சேமிக்கப்படாது. டிராக்பேக்குகளும் பிங்பேக்குகளும் கைவிடப்படும்.',
    'Mention Draco Insomnis in the footer of confirmation e-mails' => 'உறுதிப்படுத்தல் மின்னஞ்சல்களின் கீழே Draco Insomnis-ஐக் குறிப்பிடு',
    'Waiting for confirmation' => 'உறுதிப்படுத்தலுக்காகக் காத்திருக்கிறது',
    'Confirmed' => 'உறுதிப்படுத்தப்பட்டது',
    'Expired without confirmation' => 'உறுதிப்படுத்தாமல் காலாவதியானது',
    'Account' => 'கணக்கு',
    'Comment' => 'கருத்து',
    'Message' => 'செய்தி',
    'Recent submissions' => 'சமீபத்தில் அனுப்பியவை',
    'Each submission is kept for 90 days, confirmed or not. "Block" works on any row: confirming only proves the mailbox exists, not that it can be trusted. "Deliver now" lets a real submission through without waiting.' => 'ஒவ்வொரு அனுப்புதலும் உறுதிப்படுத்தப்பட்டாலும் இல்லாவிட்டாலும் 90 நாட்கள் வைக்கப்படும். "தடு" எந்த வரிசையிலும் வேலை செய்யும்: உறுதிப்படுத்தல் அஞ்சல்பெட்டி இருப்பதை மட்டுமே நிரூபிக்கிறது, நம்பத்தகுந்தது என்பதை அல்ல. "இப்போதே அனுப்பு" ஒரு உண்மையான அனுப்புதலைக் காத்திருக்காமல் கடத்திவிடும்.',
    'Type' => 'வகை',
    'Where' => 'எங்கே',
    'E-mail' => 'மின்னஞ்சல்',
    'Status' => 'நிலை',
    'Deliver now' => 'இப்போதே அனுப்பு',
    'No submissions yet.' => 'இன்னும் எதுவும் அனுப்பப்படவில்லை.',
    'Enter your email to comment: we will send you a link to confirm your comment.' => 'கருத்திட உங்கள் மின்னஞ்சலை உள்ளிடவும்: உங்கள் கருத்தை உறுதிப்படுத்த ஓர் இணைப்பை அனுப்புவோம்.',
    'The comment could not be posted: the post no longer exists or the comment is a duplicate.' => 'கருத்தை வெளியிட முடியவில்லை: இடுகை இப்போது இல்லை அல்லது கருத்து நகலானது.',
    'Your comment has been published. Thank you.' => 'உங்கள் கருத்து வெளியிடப்பட்டது. நன்றி.',
    'Your comment has been sent. It will appear once it has been reviewed. Thank you.' => 'உங்கள் கருத்து அனுப்பப்பட்டது. மதிப்பாய்வுக்குப் பிறகு தோன்றும். நன்றி.',
    'Almost done: we have sent you an email. Your comment will not be sent until you confirm it from that email. If you cannot see it, check your spam folder.' => 'கிட்டத்தட்ட முடிந்தது: உங்களுக்கு ஒரு மின்னஞ்சல் அனுப்பியுள்ளோம். அந்த மின்னஞ்சலிலிருந்து நீங்கள் உறுதிப்படுத்தும் வரை உங்கள் கருத்து அனுப்பப்படாது. அது தெரியவில்லை என்றால், ஸ்பேம் கோப்புறையைப் பாருங்கள்.',
    'Form verification of OPNV-WP is already on in this site. Use one of them, not both.' => 'இந்தத் தளத்தில் OPNV-WP-இன் படிவச் சரிபார்ப்பு ஏற்கனவே இயக்கத்தில் உள்ளது. இரண்டில் ஒன்றைப் பயன்படுத்துங்கள், இரண்டையும் அல்ல.',
    'Without SMTP the confirmation mail may not arrive and messages would be lost. Set up Site mail (SMTP) first.' => 'SMTP இல்லாமல் உறுதிப்படுத்தல் மின்னஞ்சல் வராமல் போகலாம், செய்திகள் இழக்கப்படும். முதலில் தள மின்னஞ்சலை (SMTP) அமைக்கவும்.',
    'Spam? Block this sender' => 'ஸ்பேமா? இந்த அனுப்புநரைத் தடு',
    'Almost done: we have sent you an email. Your message will not be delivered until you confirm it from that email. If you cannot see it, check your spam folder.' => 'கிட்டத்தட்ட முடிந்தது: உங்களுக்கு ஒரு மின்னஞ்சல் அனுப்பியுள்ளோம். அந்த மின்னஞ்சலிலிருந்து நீங்கள் உறுதிப்படுத்தும் வரை உங்கள் செய்தி வழங்கப்படாது. அது தெரியவில்லை என்றால், ஸ்பேம் கோப்புறையைப் பாருங்கள்.',
    'Confirm your account at %s' => '%s-இல் உங்கள் கணக்கை உறுதிப்படுத்தவும்',
    'We received a request to create an account at %s with this address.' => 'இந்த முகவரியுடன் %s-இல் கணக்கு உருவாக்கக் கோரிக்கை பெற்றோம்.',
    'To activate it, open this link and press the confirm button:' => 'அதைச் செயல்படுத்த, இந்த இணைப்பைத் திறந்து உறுதிப்படுத்து பொத்தானை அழுத்தவும்:',
    'The link expires in %d hours. If this wasn\'t you, ignore this email: the account will not be activated.' => 'இணைப்பு %d மணி நேரத்தில் காலாவதியாகும். இது நீங்கள் இல்லையென்றால், இந்த மின்னஞ்சலைப் புறக்கணிக்கவும்: கணக்கு செயல்படுத்தப்படாது.',
    'Confirm your comment at %s' => '%s-இல் உங்கள் கருத்தை உறுதிப்படுத்தவும்',
    'We received a comment at %s with this address.' => 'இந்த முகவரியுடன் %s-இல் ஒரு கருத்தைப் பெற்றோம்.',
    'It has not been sent yet and nobody has seen it. To send it, open this link and press the confirm button:' => 'இது இன்னும் அனுப்பப்படவில்லை, யாரும் பார்க்கவில்லை. அனுப்ப, இந்த இணைப்பைத் திறந்து உறுதிப்படுத்து பொத்தானை அழுத்தவும்:',
    'The link expires in %d hours. If this wasn\'t you, ignore this email: the comment will be deleted.' => 'இணைப்பு %d மணி நேரத்தில் காலாவதியாகும். இது நீங்கள் இல்லையென்றால், இந்த மின்னஞ்சலைப் புறக்கணிக்கவும்: கருத்து நீக்கப்படும்.',
    'Confirm your message to %s' => '%s-க்கு அனுப்பிய உங்கள் செய்தியை உறுதிப்படுத்தவும்',
    'We received a message sent through the form at %s with this address.' => 'இந்த முகவரியுடன் %s-இன் படிவம் வழியாக அனுப்பப்பட்ட ஒரு செய்தியைப் பெற்றோம்.',
    'It has not been delivered yet. To send it, open this link and press the confirm button:' => 'இது இன்னும் வழங்கப்படவில்லை. அனுப்ப, இந்த இணைப்பைத் திறந்து உறுதிப்படுத்து பொத்தானை அழுத்தவும்:',
    'The link expires in %d hours. If this wasn\'t you, ignore this email: the message will be deleted.' => 'இணைப்பு %d மணி நேரத்தில் காலாவதியாகும். இது நீங்கள் இல்லையென்றால், இந்த மின்னஞ்சலைப் புறக்கணிக்கவும்: செய்தி நீக்கப்படும்.',
    'Confirm' => 'உறுதிப்படுத்து',
    'The registration could not be completed.' => 'பதிவை முடிக்க முடியவில்லை.',
    'Access unavailable.' => 'அணுகல் கிடைக்கவில்லை.',
    'Almost done: we have sent you an email. Your account will not be activated until you confirm it from that email. If you cannot see it, check your spam folder.' => 'கிட்டத்தட்ட முடிந்தது: உங்களுக்கு ஒரு மின்னஞ்சல் அனுப்பியுள்ளோம். அந்த மின்னஞ்சலிலிருந்து நீங்கள் உறுதிப்படுத்தும் வரை உங்கள் கணக்கு செயல்படுத்தப்படாது. அது தெரியவில்லை என்றால், ஸ்பேம் கோப்புறையைப் பாருங்கள்.',
    'This link was already used or has expired. If your message did not arrive, send it again from the form.' => 'இந்த இணைப்பு ஏற்கனவே பயன்படுத்தப்பட்டது அல்லது காலாவதியானது. உங்கள் செய்தி வரவில்லை என்றால், படிவத்திலிருந்து மீண்டும் அனுப்பவும்.',
    'Press the button to activate your account.' => 'உங்கள் கணக்கைச் செயல்படுத்த பொத்தானை அழுத்தவும்.',
    'Press the button to send your comment.' => 'உங்கள் கருத்தை அனுப்ப பொத்தானை அழுத்தவும்.',
    'Press the button to send your message.' => 'உங்கள் செய்தியை அனுப்ப பொத்தானை அழுத்தவும்.',
    'This link was already used. Thank you.' => 'இந்த இணைப்பு ஏற்கனவே பயன்படுத்தப்பட்டது. நன்றி.',
    'Your account is now active. Thank you.' => 'உங்கள் கணக்கு இப்போது செயலில் உள்ளது. நன்றி.',
    'Your message has been sent. Thank you.' => 'உங்கள் செய்தி அனுப்பப்பட்டது. நன்றி.',
    'Two-step login' => 'இரண்டு-படி உள்நுழைவு',
    'After the right password, WordPress asks for a 6-digit code sent by e-mail. A stolen password alone is no longer enough to get in.' => 'சரியான கடவுச்சொல்லுக்குப் பிறகு, மின்னஞ்சலில் அனுப்பப்பட்ட 6 இலக்கக் குறியீட்டை WordPress கேட்கும். திருடப்பட்ட கடவுச்சொல் மட்டும் இனி உள்ளே நுழையப் போதாது.',
    'DRACO_MFA_OFF is set in wp-config.php: no codes are asked for. Remove that line once you are back in.' => 'wp-config.php-இல் DRACO_MFA_OFF அமைக்கப்பட்டுள்ளது: குறியீடு கேட்கப்படாது. மீண்டும் உள்ளே நுழைந்ததும் அந்த வரியை நீக்கவும்.',
    'Ask for a code by e-mail after the password' => 'கடவுச்சொல்லுக்குப் பிறகு மின்னஞ்சல் குறியீட்டைக் கேள்',
    'Who has to enter it:' => 'யார் உள்ளிட வேண்டும்:',
    'Administrators' => 'நிர்வாகிகள்',
    'Anyone who can write or edit content' => 'உள்ளடக்கத்தை எழுதக்கூடிய அல்லது திருத்தக்கூடிய எவரும்',
    'Every user' => 'அனைத்துப் பயனர்களும்',
    'Offer "Trust this device for %d days"' => '"இந்தச் சாதனத்தை %d நாட்கள் நம்பு" என்பதை வழங்கு',
    'Good to know' => 'தெரிந்து கொள்ள வேண்டியவை',
    'It can only be switched on with Site mail (SMTP) working, and it switches itself off if that connection is forgotten: a code that never arrives would lock you out.' => 'தள மின்னஞ்சல் (SMTP) வேலை செய்யும்போது மட்டுமே இதை இயக்க முடியும்; அந்த இணைப்பு மறக்கப்பட்டால் தானாக அணையும்: ஒருபோதும் வராத குறியீடு உங்களை வெளியே பூட்டிவிடும்.',
    'The code is only sent after the right password. It expires in 10 minutes and allows 5 tries; repeated failures block the address for 15 minutes.' => 'சரியான கடவுச்சொல்லுக்குப் பிறகு மட்டுமே குறியீடு அனுப்பப்படும். அது 10 நிமிடங்களில் காலாவதியாகும், 5 முயற்சிகள் அனுமதிக்கப்படும்; தொடர் தோல்விகள் முகவரியை 15 நிமிடங்களுக்குத் தடுக்கும்.',
    'Changing the password or the e-mail of an account makes all its trusted devices ask for a code again.' => 'ஒரு கணக்கின் கடவுச்சொல் அல்லது மின்னஞ்சலை மாற்றினால், அதன் அனைத்து நம்பகச் சாதனங்களும் மீண்டும் குறியீடு கேட்கும்.',
    'Login boxes that work without reloading the page (some themes) cannot show the code step: those users are asked to log in from the normal login page.' => 'பக்கத்தை மீண்டும் ஏற்றாமல் இயங்கும் உள்நுழைவுப் பெட்டிகள் (சில தீம்களில்) குறியீட்டுப் படியைக் காட்ட முடியாது: அந்தப் பயனர்கள் சாதாரண உள்நுழைவுப் பக்கத்திலிருந்து உள்நுழையக் கேட்கப்படுவார்கள்.',
    'If you are ever locked out, add define(\'DRACO_MFA_OFF\', true); to wp-config.php, log in, fix the problem and remove the line. Only someone with access to the server can do this, unlike a "skip" button.' => 'நீங்கள் வெளியே பூட்டப்பட்டால், wp-config.php-இல் define(\'DRACO_MFA_OFF\', true); சேர்த்து, உள்நுழைந்து, பிரச்சினையைச் சரிசெய்து, அந்த வரியை நீக்கவும். "தவிர்" பொத்தானைப் போலன்றி, சர்வர் அணுகல் உள்ளவர் மட்டுமே இதைச் செய்ய முடியும்.',
    'The e-mail login code of OPNV-WP is already on in this site. Use one of them, not both.' => 'இந்தத் தளத்தில் OPNV-WP-இன் மின்னஞ்சல் உள்நுழைவுக் குறியீடு ஏற்கனவே இயக்கத்தில் உள்ளது. இரண்டில் ஒன்றைப் பயன்படுத்துங்கள், இரண்டையும் அல்ல.',
    'Without SMTP the code may not arrive and you would be locked out. Set up Site mail (SMTP) first.' => 'SMTP இல்லாமல் குறியீடு வராமல் போகலாம், நீங்கள் வெளியே பூட்டப்படுவீர்கள். முதலில் தள மின்னஞ்சலை (SMTP) அமைக்கவும்.',
    'Too many attempts. Try again later.' => 'அதிகமான முயற்சிகள். பிறகு மீண்டும் முயலவும்.',
    'This account needs a code sent by e-mail. Log in from %s to receive it.' => 'இந்தக் கணக்கிற்கு மின்னஞ்சலில் அனுப்பப்படும் குறியீடு தேவை. அதைப் பெற %s-இலிருந்து உள்நுழையவும்.',
    'The login code could not be sent by e-mail. If you own this site and are locked out, add define(\'DRACO_MFA_OFF\', true); to wp-config.php.' => 'உள்நுழைவுக் குறியீட்டை மின்னஞ்சலில் அனுப்ப முடியவில்லை. நீங்கள் இந்தத் தளத்தின் உரிமையாளராக இருந்து வெளியே பூட்டப்பட்டிருந்தால், wp-config.php-இல் define(\'DRACO_MFA_OFF\', true); சேர்க்கவும்.',
    'Hello %s,' => 'வணக்கம் %s,',
    '[%s] Confirm your recovery e-mail' => '[%s] உங்கள் மீட்பு மின்னஞ்சலை உறுதிப்படுத்தவும்',
    'Confirm your recovery e-mail' => 'உங்கள் மீட்பு மின்னஞ்சலை உறுதிப்படுத்தவும்',
    'Type this code in the recovery e-mail screen to confirm the change:' => 'மாற்றத்தை உறுதிப்படுத்த, மீட்பு மின்னஞ்சல் திரையில் இந்தக் குறியீட்டை உள்ளிடவும்:',
    'It expires in 15 minutes. If you did not ask for this, someone has access to your account: change your password.' => 'இது 15 நிமிடங்களில் காலாவதியாகும். நீங்கள் இதைக் கேட்கவில்லை என்றால், யாரோ உங்கள் கணக்கை அணுகுகிறார்கள்: உங்கள் கடவுச்சொல்லை மாற்றவும்.',
    '[%s] Your login code' => '[%s] உங்கள் உள்நுழைவுக் குறியீடு',
    'Your login code' => 'உங்கள் உள்நுழைவுக் குறியீடு',
    'Use this code to finish logging in:' => 'உள்நுழைவை முடிக்க இந்தக் குறியீட்டைப் பயன்படுத்தவும்:',
    'It expires in %d minutes. If you did not try to log in, someone knows your password: change it.' => 'இது %d நிமிடங்களில் காலாவதியாகும். நீங்கள் உள்நுழைய முயலவில்லை என்றால், யாருக்கோ உங்கள் கடவுச்சொல் தெரியும்: அதை மாற்றவும்.',
    'The code has expired. Log in again.' => 'குறியீடு காலாவதியானது. மீண்டும் உள்நுழையவும்.',
    'The recovery e-mail cannot be used right now. Try again later.' => 'மீட்பு மின்னஞ்சலை இப்போது பயன்படுத்த முடியாது. பிறகு மீண்டும் முயலவும்.',
    'A new code is on its way. Check your spam folder too.' => 'புதிய குறியீடு வருகிறது. ஸ்பேம் கோப்புறையையும் பாருங்கள்.',
    'The code could not be sent again.' => 'குறியீட்டை மீண்டும் அனுப்ப முடியவில்லை.',
    'Too many attempts. Log in again.' => 'அதிகமான முயற்சிகள். மீண்டும் உள்நுழையவும்.',
    'Wrong code.' => 'தவறான குறியீடு.',
    'We have sent a 6-digit code to %s. Check your spam folder too.' => '%s-க்கு 6 இலக்கக் குறியீட்டை அனுப்பியுள்ளோம். ஸ்பேம் கோப்புறையையும் பாருங்கள்.',
    'Login code' => 'உள்நுழைவுக் குறியீடு',
    'Code' => 'குறியீடு',
    'Trust this device for %d days' => 'இந்தச் சாதனத்தை %d நாட்கள் நம்பு',
    'Remember me' => 'என்னை நினைவில் வை',
    'Verify and log in' => 'சரிபார்த்து உள்நுழை',
    'Send the code again' => 'குறியீட்டை மீண்டும் அனுப்பு',
    'I cannot reach this mailbox: use my recovery e-mail' => 'இந்த அஞ்சல்பெட்டியை என்னால் அணுக முடியவில்லை: என் மீட்பு மின்னஞ்சலைப் பயன்படுத்து',
    '← Back to log in' => '← உள்நுழைவுக்குத் திரும்பு',
    'Access restricted' => 'அணுகல் கட்டுப்படுத்தப்பட்டுள்ளது',
    'Recovery e-mail' => 'மீட்பு மின்னஞ்சல்',
    'Your recovery e-mail has been changed.' => 'உங்கள் மீட்பு மின்னஞ்சல் மாற்றப்பட்டது.',
    'This address is no longer your recovery e-mail.' => 'இந்த முகவரி இனி உங்கள் மீட்பு மின்னஞ்சல் அல்ல.',
    'Your password has been reset. The next login code will be sent to this address.' => 'உங்கள் கடவுச்சொல் மீட்டமைக்கப்பட்டது. அடுத்த உள்நுழைவுக் குறியீடு இந்த முகவரிக்கு அனுப்பப்படும்.',
    'The main e-mail of your account has been changed.' => 'உங்கள் கணக்கின் முதன்மை மின்னஞ்சல் மாற்றப்பட்டது.',
    'If this was not you, log in with your recovery e-mail and change your password.' => 'இது நீங்கள் இல்லையென்றால், உங்கள் மீட்பு மின்னஞ்சலுடன் உள்நுழைந்து கடவுச்சொல்லை மாற்றவும்.',
    'Security notice' => 'பாதுகாப்பு அறிவிப்பு',
    'We have sent a code to the new address. Type it below.' => 'புதிய முகவரிக்குக் குறியீட்டை அனுப்பியுள்ளோம். கீழே உள்ளிடவும்.',
    'Recovery e-mail saved.' => 'மீட்பு மின்னஞ்சல் சேமிக்கப்பட்டது.',
    'That e-mail address is not valid.' => 'அந்த மின்னஞ்சல் முகவரி செல்லாது.',
    'It must be different from the main e-mail of your account, or it would be no use if that one fails.' => 'இது உங்கள் கணக்கின் முதன்மை மின்னஞ்சலிலிருந்து வேறுபட்டிருக்க வேண்டும்; இல்லையெனில் அது தோல்வியுற்றால் பயனில்லை.',
    'The code could not be sent. Check Site mail (SMTP).' => 'குறியீட்டை அனுப்ப முடியவில்லை. தள மின்னஞ்சலை (SMTP) சரிபார்க்கவும்.',
    'The codes expired or were tried too many times. Start again.' => 'குறியீடுகள் காலாவதியாகிவிட்டன அல்லது பலமுறை முயற்சிக்கப்பட்டன. மீண்டும் தொடங்கவும்.',
    'Cancelled.' => 'ரத்து செய்யப்பட்டது.',
    'Your account needs a login code. Add a recovery e-mail before going on: it is your way back in if your main mailbox fails or is stolen.' => 'உங்கள் கணக்கிற்கு உள்நுழைவுக் குறியீடு தேவை. தொடர்வதற்கு முன் ஒரு மீட்பு மின்னஞ்சலைச் சேர்க்கவும்: உங்கள் முதன்மை அஞ்சல்பெட்டி தோல்வியுற்றாலோ திருடப்பட்டாலோ அதுவே திரும்பி வரும் வழி.',
    'A second mailbox for your login code, like the PUK of a phone. Use one on another provider than your main e-mail (for example Gmail if the main one is on this site\'s domain).' => 'உங்கள் உள்நுழைவுக் குறியீட்டுக்கான இரண்டாவது அஞ்சல்பெட்டி, தொலைபேசியின் PUK போல. உங்கள் முதன்மை மின்னஞ்சலிலிருந்து வேறு வழங்குநரைப் பயன்படுத்தவும் (உதாரணமாக, முதன்மையானது இந்தத் தளத்தின் டொமைனில் இருந்தால் Gmail).',
    'On the code screen you can ask for the code to go to this address instead.' => 'குறியீட்டுத் திரையில் குறியீட்டை இந்த முகவரிக்கு அனுப்பக் கேட்கலாம்.',
    '"Lost your password?" also accepts this address, and the link goes there.' => '"கடவுச்சொல் மறந்துவிட்டதா?" இந்த முகவரியையும் ஏற்கும், இணைப்பு அங்கே செல்லும்.',
    'After a password reset, the next code goes only to this address.' => 'கடவுச்சொல் மீட்டமைப்புக்குப் பிறகு, அடுத்த குறியீடு இந்த முகவரிக்கு மட்டுமே செல்லும்.',
    'Any change to it, or to your main e-mail, is told to the other mailbox.' => 'இதில் அல்லது உங்கள் முதன்மை மின்னஞ்சலில் எந்த மாற்றமும் மற்ற அஞ்சல்பெட்டிக்குத் தெரிவிக்கப்படும்.',
    'Current recovery e-mail: %s' => 'தற்போதைய மீட்பு மின்னஞ்சல்: %s',
    'You have no recovery e-mail yet.' => 'உங்களுக்கு இன்னும் மீட்பு மின்னஞ்சல் இல்லை.',
    'Code sent to %s' => '%s-க்குக் குறியீடு அனுப்பப்பட்டது',
    'Code sent to your current recovery e-mail %s' => 'உங்கள் தற்போதைய மீட்பு மின்னஞ்சல் %s-க்குக் குறியீடு அனுப்பப்பட்டது',
    'Cancel' => 'ரத்து செய்',
    'New recovery e-mail' => 'புதிய மீட்பு மின்னஞ்சல்',
    'A code will go to the new address and another to the current one: both are needed, so nobody can change it with your session alone.' => 'ஒரு குறியீடு புதிய முகவரிக்கும் மற்றொன்று தற்போதைய முகவரிக்கும் செல்லும்: இரண்டும் தேவை, எனவே உங்கள் அமர்வை மட்டும் வைத்து யாரும் அதை மாற்ற முடியாது.',
    'Send code' => 'குறியீட்டை அனுப்பு',
    'Site mail (SMTP)' => 'தள மின்னஞ்சல் (SMTP)',
    'The full address of the mailbox, with @ and domain. Not your WordPress username.' => 'அஞ்சல்பெட்டியின் முழு முகவரி, @ மற்றும் டொமைனுடன். உங்கள் WordPress பயனர் பெயர் அல்ல.',
    'The password of that mailbox, not the one for WordPress or your hosting. If you do not remember it, change it in your hosting or domain panel, in the e-mail section.' => 'அந்த அஞ்சல்பெட்டியின் கடவுச்சொல், WordPress அல்லது ஹோஸ்டிங்குடையது அல்ல. நினைவில் இல்லையென்றால், ஹோஸ்டிங் அல்லது டொமைன் பேனலின் மின்னஞ்சல் பகுதியில் மாற்றவும்.',
    'An app password, created in the security settings of your account. Not your normal password.' => 'உங்கள் கணக்கின் பாதுகாப்பு அமைப்புகளில் உருவாக்கப்படும் செயலிக் கடவுச்சொல். உங்கள் வழக்கமான கடவுச்சொல் அல்ல.',
    'Your full address.' => 'உங்கள் முழு முகவரி.',
    'The mailbox password, or an app password if you use two-step verification.' => 'அஞ்சல்பெட்டியின் கடவுச்சொல், அல்லது இரண்டு-படி சரிபார்ப்பைப் பயன்படுத்தினால் செயலிக் கடவுச்சொல்.',
    'The mailbox password or an app password. SMTP sending must be allowed in Microsoft 365.' => 'அஞ்சல்பெட்டியின் கடவுச்சொல் அல்லது செயலிக் கடவுச்சொல். Microsoft 365-இல் SMTP அனுப்புதல் அனுமதிக்கப்பட்டிருக்க வேண்டும்.',
    'The full address of the Google account.' => 'Google கணக்கின் முழு முகவரி.',
    'The SMTP login shown in your Brevo account.' => 'உங்கள் Brevo கணக்கில் காட்டப்படும் SMTP உள்நுழைவு.',
    'The Brevo SMTP key, not your account password.' => 'Brevo-வின் SMTP விசை, கணக்குக் கடவுச்சொல் அல்ல.',
    'The SMTP user of your domain in Mailgun.' => 'Mailgun-இல் உங்கள் டொமைனின் SMTP பயனர்.',
    'The SMTP password of that user.' => 'அந்தப் பயனரின் SMTP கடவுச்சொல்.',
    'Type literally: apikey' => 'அப்படியே தட்டச்சு செய்யவும்: apikey',
    'Your SendGrid API key.' => 'உங்கள் SendGrid API விசை.',
    'The Postmark Server API Token.' => 'Postmark-இன் Server API Token.',
    'The same Server API Token.' => 'அதே Server API Token.',
    'Your Mailjet API key.' => 'உங்கள் Mailjet API விசை.',
    'Your Mailjet secret key.' => 'உங்கள் Mailjet இரகசிய விசை.',
    'The SMTP user created in Amazon SES.' => 'Amazon SES-இல் உருவாக்கப்பட்ட SMTP பயனர்.',
    'The Amazon SES SMTP password, not your AWS password.' => 'Amazon SES SMTP கடவுச்சொல், உங்கள் AWS கடவுச்சொல் அல்ல.',
    'Sends the mail of this site through a real mailbox with its password, instead of the server\'s mail() function. Without it, many messages are silently rejected: login codes, forms and orders.' => 'சர்வரின் mail() செயல்பாட்டுக்குப் பதிலாக, ஓர் உண்மையான அஞ்சல்பெட்டி மற்றும் அதன் கடவுச்சொல் மூலம் இந்தத் தளத்தின் மின்னஞ்சலை அனுப்புகிறது. இது இல்லாமல் பல செய்திகள் அமைதியாக நிராகரிக்கப்படும்: உள்நுழைவுக் குறியீடுகள், படிவங்கள், ஆர்டர்கள்.',
    'The saved password can no longer be read (the site\'s security keys changed). Type it again and repeat the test.' => 'சேமித்த கடவுச்சொல்லை இனி படிக்க முடியாது (தளத்தின் பாதுகாப்பு விசைகள் மாறிவிட்டன). மீண்டும் தட்டச்சு செய்து சோதனையை மீண்டும் செய்யவும்.',
    '%s is sending the mail of this site. Turn it off before testing or switching on this module.' => '%s இந்தத் தளத்தின் மின்னஞ்சலை அனுப்புகிறது. சோதிக்கும் முன் அல்லது இந்தத் தொகுதியை இயக்கும் முன் அதை அணைக்கவும்.',
    'The domain has DMARC "%s" and this site sends with PHP mail(): messages, including login codes, may never arrive even though the site says "sent".' => 'டொமைனுக்கு DMARC "%s" உள்ளது, இந்தத் தளம் PHP mail() மூலம் அனுப்புகிறது: தளம் "அனுப்பப்பட்டது" என்று சொன்னாலும், உள்நுழைவுக் குறியீடுகள் உட்பட செய்திகள் ஒருபோதும் வராமல் போகலாம்.',
    'The sender %1$s is not from the domain of this site. Use an @%2$s address or messages may be rejected.' => 'அனுப்புநர் %1$s இந்தத் தளத்தின் டொமைனைச் சேர்ந்தவர் அல்ல. @%2$s முகவரியைப் பயன்படுத்தவும், இல்லையெனில் செய்திகள் நிராகரிக்கப்படலாம்.',
    'Sending through SMTP as %s' => '%s ஆக SMTP மூலம் அனுப்புகிறது',
    'Sending through %s' => '%s மூலம் அனுப்புகிறது',
    'Sending with PHP mail()' => 'PHP mail() மூலம் அனுப்புகிறது',
    '1. Connection' => '1. இணைப்பு',
    'Save connection' => 'இணைப்பைச் சேமி',
    '2. Test' => '2. சோதனை',
    'Save the connection to send tests.' => 'சோதனைகளை அனுப்ப இணைப்பைச் சேமிக்கவும்.',
    'Send a test and check that it arrived, also in spam. "Accepted" only means the server took it.' => 'ஒரு சோதனையை அனுப்பி, அது வந்ததா எனப் பாருங்கள், ஸ்பேமிலும். "ஏற்கப்பட்டது" என்றால் சர்வர் அதைப் பெற்றது என்று மட்டுமே பொருள்.',
    'Send a test to' => 'இதற்குச் சோதனை அனுப்பு',
    'Send test' => 'சோதனை அனுப்பு',
    '3. Switch on' => '3. இயக்கு',
    'Until this step, the site keeps sending as before.' => 'இந்தப் படி வரை, தளம் முன்பு போலவே அனுப்பும்.',
    'This forgets the connection above (server, user, password and sender) and goes back to PHP mail(). Modules that send login codes are switched off, because the codes might not arrive.' => 'இது மேலே உள்ள இணைப்பை (சர்வர், பயனர், கடவுச்சொல், அனுப்புநர்) மறந்து PHP mail()-க்குத் திரும்பும். உள்நுழைவுக் குறியீடுகளை அனுப்பும் தொகுதிகள் அணைக்கப்படும், ஏனெனில் குறியீடுகள் வராமல் போகலாம்.',
    'Go back to PHP mail() and forget the connection' => 'PHP mail()-க்குத் திரும்பி இணைப்பை மற',
    'Switch on SMTP for this site' => 'இந்தத் தளத்திற்கு SMTP-ஐ இயக்கு',
    'It can be switched on once a test succeeds.' => 'ஒரு சோதனை வெற்றிபெற்றதும் இயக்கலாம்.',
    'Usually the full address of the mailbox. Not your WordPress username.' => 'பொதுவாக அஞ்சல்பெட்டியின் முழு முகவரி. உங்கள் WordPress பயனர் பெயர் அல்ல.',
    'The password of that mailbox, not the one for WordPress or your hosting.' => 'அந்த அஞ்சல்பெட்டியின் கடவுச்சொல், WordPress அல்லது ஹோஸ்டிங்குடையது அல்ல.',
    'Mail on your own domain (recommended)' => 'உங்கள் சொந்த டொமைனில் மின்னஞ்சல் (பரிந்துரைக்கப்படுகிறது)',
    'Sending services' => 'அனுப்பும் சேவைகள்',
    'Personal mail (not recommended)' => 'தனிப்பட்ட மின்னஞ்சல் (பரிந்துரைக்கப்படவில்லை)',
    'Choose your provider…' => 'உங்கள் வழங்குநரைத் தேர்ந்தெடுக்கவும்…',
    'Where is your mailbox?' => 'உங்கள் அஞ்சல்பெட்டி எங்கே உள்ளது?',
    'Preferably a mailbox on the domain of this site, @%1$s. This fills in server, encryption and port. If your provider is not listed, the server is usually mail.%2$s: type it by hand and confirm it with them.' => 'இந்தத் தளத்தின் டொமைனில் உள்ள அஞ்சல்பெட்டி சிறந்தது, @%1$s. இது சர்வர், குறியாக்கம், போர்ட் ஆகியவற்றை நிரப்பும். உங்கள் வழங்குநர் பட்டியலில் இல்லையென்றால், சர்வர் பொதுவாக mail.%2$s: கைமுறையாகத் தட்டச்சு செய்து அவர்களிடம் உறுதிப்படுத்தவும்.',
    'Outgoing server (SMTP)' => 'வெளிச்செல்லும் சர்வர் (SMTP)',
    'The address of the server that sends the mail. Your provider gives it to you.' => 'மின்னஞ்சலை அனுப்பும் சர்வரின் முகவரி. உங்கள் வழங்குநர் தருவார்.',
    'Encryption and port' => 'குறியாக்கமும் போர்ட்டும்',
    'Port' => 'போர்ட்',
    'Use what your provider says. If it does not connect, try the other option.' => 'உங்கள் வழங்குநர் சொல்வதைப் பயன்படுத்தவும். இணையவில்லை என்றால், மற்ற தேர்வை முயலவும்.',
    'Username' => 'பயனர் பெயர்',
    'Password' => 'கடவுச்சொல்',
    'Saved. Leave empty to keep it' => 'சேமிக்கப்பட்டது. அப்படியே வைக்கக் காலியாக விடவும்',
    'It is stored encrypted.' => 'குறியாக்கம் செய்து சேமிக்கப்படுகிறது.',
    'Sender address (optional)' => 'அனுப்புநர் முகவரி (விருப்பத்தேர்வு)',
    'The address people see. Empty uses the username above, which is normal. If you fill it in, it must be a mailbox or authorised alias on the domain of this site.' => 'மக்கள் பார்க்கும் முகவரி. காலியாக இருந்தால் மேலே உள்ள பயனர் பெயர் பயன்படுத்தப்படும், அது இயல்பானது. நிரப்பினால், அது இந்தத் தளத்தின் டொமைனில் உள்ள அஞ்சல்பெட்டி அல்லது அங்கீகரிக்கப்பட்ட மாற்றுப்பெயராக இருக்க வேண்டும்.',
    'Sender name (optional)' => 'அனுப்புநர் பெயர் (விருப்பத்தேர்வு)',
    'The name people see. Empty keeps whatever each plugin sets, usually "WordPress".' => 'மக்கள் பார்க்கும் பெயர். காலியாக இருந்தால் ஒவ்வொரு செருகுநிரலும் அமைப்பது அப்படியே இருக்கும், பொதுவாக "WordPress".',
    'Addresses for security alerts' => 'பாதுகாப்பு எச்சரிக்கைகளுக்கான முகவரிகள்',
    'One per line. Besides the administrator, they receive the WordPress link to get in and fix the site if a plugin or theme breaks it (it gives access to the dashboard: trusted mailboxes only), and password-change alerts. Put at least one that is not @%s: if this domain fails, alerts still arrive.' => 'ஒரு வரிக்கு ஒன்று. நிர்வாகியுடன் கூடுதலாக, ஒரு செருகுநிரல் அல்லது தீம் தளத்தை உடைத்தால் உள்ளே சென்று சரிசெய்ய WordPress இணைப்பையும் (இது டாஷ்போர்டு அணுகலைத் தரும்: நம்பகமான அஞ்சல்பெட்டிகள் மட்டும்), கடவுச்சொல் மாற்ற எச்சரிக்கைகளையும் இவர்கள் பெறுவார்கள். @%s அல்லாத ஒன்றையாவது சேர்க்கவும்: இந்த டொமைன் தோல்வியுற்றாலும் எச்சரிக்கைகள் வரும்.',
    'The username is not an e-mail address: type an address on this domain in "Sender address".' => 'பயனர் பெயர் மின்னஞ்சல் முகவரி அல்ல: "அனுப்புநர் முகவரி"-இல் இந்த டொமைனில் உள்ள ஒரு முகவரியைத் தட்டச்சு செய்யவும்.',
    'This sender is not from the domain of this site. Use an @%s address or messages may be rejected.' => 'இந்த அனுப்புநர் இந்தத் தளத்தின் டொமைனைச் சேர்ந்தவர் அல்ல. @%s முகவரியைப் பயன்படுத்தவும், இல்லையெனில் செய்திகள் நிராகரிக்கப்படலாம்.',
    'Connection saved. Now send a test.' => 'இணைப்பு சேமிக்கப்பட்டது. இப்போது ஒரு சோதனையை அனுப்பவும்.',
    'SMTP switched on. The mail of this site now leaves through your mailbox.' => 'SMTP இயக்கப்பட்டது. இந்தத் தளத்தின் மின்னஞ்சல் இப்போது உங்கள் அஞ்சல்பெட்டி வழியாகச் செல்கிறது.',
    'Connection forgotten. The site sends with PHP mail() again. The alert addresses were kept.' => 'இணைப்பு மறக்கப்பட்டது. தளம் மீண்டும் PHP mail() மூலம் அனுப்புகிறது. எச்சரிக்கை முகவரிகள் வைக்கப்பட்டுள்ளன.',
    'Test sent to %s. The server accepted it: check that it arrived, also in spam.' => '%s-க்குச் சோதனை அனுப்பப்பட்டது. சர்வர் ஏற்றது: அது வந்ததா எனப் பாருங்கள், ஸ்பேமிலும்.',
    'Missing data. Check server, username, password, sender and recipient.' => 'தரவு குறைவாக உள்ளது. சர்வர், பயனர் பெயர், கடவுச்சொல், அனுப்புநர், பெறுநர் ஆகியவற்றைச் சரிபார்க்கவும்.',
    'Not saved: the password could not be encrypted (OpenSSL is missing on the server).' => 'சேமிக்கப்படவில்லை: கடவுச்சொல்லைக் குறியாக்க முடியவில்லை (சர்வரில் OpenSSL இல்லை).',
    'A successful test with this connection is needed first.' => 'முதலில் இந்த இணைப்புடன் ஒரு வெற்றிகரமான சோதனை தேவை.',
    'Another plugin is sending the mail of this site. Turn it off first.' => 'வேறொரு செருகுநிரல் இந்தத் தளத்தின் மின்னஞ்சலை அனுப்புகிறது. முதலில் அதை அணைக்கவும்.',
    'The test to %1$s failed: %2$s' => '%1$s-க்கான சோதனை தோல்வியுற்றது: %2$s',
    'Another plugin' => 'வேறொரு செருகுநிரல்',
    'Recent messages' => 'சமீபத்திய செய்திகள்',
    '"Accepted" means the server took it, not that it reached the inbox. With PHP mail(), not even that. Message bodies are never stored.' => '"ஏற்கப்பட்டது" என்றால் சர்வர் அதைப் பெற்றது, இன்பாக்ஸை அடைந்தது என்பதல்ல. PHP mail()-இல் அதுகூட இல்லை. செய்தி உள்ளடக்கம் ஒருபோதும் சேமிக்கப்படுவதில்லை.',
    'Via' => 'வழியாக',
    'To' => 'பெறுநர்',
    'Subject' => 'பொருள்',
    'Accepted' => 'ஏற்கப்பட்டது',
    'Error: %s' => 'பிழை: %s',
    'Nothing yet.' => 'இன்னும் எதுவும் இல்லை.',
    'Open' => 'திற',
    'Automatic message from %s.' => '%s-இலிருந்து தானியங்கிச் செய்தி.',
    'Protected by Draco Insomnis · OPNV Systems.' => 'Draco Insomnis · OPNV Systems மூலம் பாதுகாக்கப்படுகிறது.',
    'The saved password can no longer be read. Type it again.' => 'சேமித்த கடவுச்சொல்லை இனி படிக்க முடியாது. மீண்டும் தட்டச்சு செய்யவும்.',
    '%s is sending the mail of this site. Turn it off first.' => '%s இந்தத் தளத்தின் மின்னஞ்சலை அனுப்புகிறது. முதலில் அதை அணைக்கவும்.',
    'Mail test · %s' => 'மின்னஞ்சல் சோதனை · %s',
    'If you can read this, the mail of your site leaves correctly through this connection.' => 'இதை நீங்கள் படிக்க முடிந்தால், உங்கள் தளத்தின் மின்னஞ்சல் இந்த இணைப்பு வழியாகச் சரியாகச் செல்கிறது.',
    'Anti-bot shield' => 'பாட் எதிர்ப்புக் கேடயம்',
    'Stops programs that create fake accounts before the account exists. The bot is told "registration complete" after a short wait, and the attempt is kept as evidence. Nothing is sent back to the attacker.' => 'போலிக் கணக்குகளை உருவாக்கும் நிரல்களைக் கணக்கு உருவாவதற்கு முன்பே நிறுத்துகிறது. சிறிது காத்திருப்புக்குப் பின் பாட்டுக்கு "பதிவு முடிந்தது" எனச் சொல்லப்படும், முயற்சி சான்றாக வைக்கப்படும். தாக்குபவருக்கு எதுவும் திருப்பி அனுப்பப்படாது.',
    'Protect sign-ups (WordPress, WooCommerce and RealHomes)' => 'பதிவுகளைப் பாதுகா (WordPress, WooCommerce மற்றும் RealHomes)',
    'Visitor address' => 'பார்வையாளர் முகவரி',
    'Connection address (safest; use this unless the site is behind a proxy)' => 'இணைப்பு முகவரி (மிகப் பாதுகாப்பானது; தளம் ப்ராக்ஸிக்குப் பின்னால் இல்லையென்றால் இதைப் பயன்படுத்தவும்)',
    'Cloudflare header (only if every visit goes through Cloudflare)' => 'Cloudflare தலைப்பு (ஒவ்வொரு வருகையும் Cloudflare வழியாக வந்தால் மட்டும்)',
    'X-Forwarded-For (only behind your own proxy or CDN)' => 'X-Forwarded-For (உங்கள் சொந்த ப்ராக்ஸி அல்லது CDN-க்குப் பின்னால் மட்டும்)',
    'Your address as the plugin sees it:' => 'செருகுநிரல் பார்க்கும் உங்கள் முகவரி:',
    'Rented-server networks to watch, besides the ones already known (one per line, e.g. 198.51.100.0/24)' => 'ஏற்கனவே தெரிந்தவை தவிர, கண்காணிக்க வேண்டிய வாடகை சர்வர் நெட்வொர்க்குகள் (ஒரு வரிக்கு ஒன்று, உ.தா. 198.51.100.0/24)',
    'Block a sender' => 'ஓர் அனுப்புநரைத் தடு',
    'For' => 'காலம்',
    'Reason' => 'காரணம்',
    'Active blocks' => 'செயலில் உள்ள தடைகள்',
    'Value' => 'மதிப்பு',
    'Until (UTC)' => 'வரை (UTC)',
    'Unblock' => 'தடையை நீக்கு',
    'None.' => 'எதுவும் இல்லை.',
    'already blocked' => 'ஏற்கனவே தடுக்கப்பட்டது',
    'asked for an admin role' => 'நிர்வாகப் பங்கைக் கேட்டது',
    'role that does not exist' => 'இல்லாத பங்கு',
    'filled the trap field' => 'பொறிப் புலத்தை நிரப்பியது',
    'forged page stamp' => 'போலிப் பக்க முத்திரை',
    'never loaded the page' => 'பக்கத்தை ஒருபோதும் ஏற்றவில்லை',
    'too fast' => 'மிக வேகமாக',
    'random username' => 'சீரற்ற பயனர் பெயர்',
    'rented server' => 'வாடகை சர்வர்',
    'repeat offender' => 'மீண்டும் மீண்டும் தவறு செய்பவர்',
    'a script, not a browser' => 'ஸ்கிரிப்ட், உலாவி அல்ல',
    'Recent suspicious attempts' => 'சமீபத்திய சந்தேகத்திற்குரிய முயற்சிகள்',
    'Kept for 90 days. Three bot attempts in a day block the address for a week. "Evidence" downloads everything from that address as a CSV file to attach to an abuse report to the network provider.' => '90 நாட்கள் வைக்கப்படும். ஒரு நாளில் மூன்று பாட் முயற்சிகள் முகவரியை ஒரு வாரத்திற்குத் தடுக்கும். "சான்று" அந்த முகவரியின் அனைத்தையும் CSV கோப்பாகப் பதிவிறக்கும், நெட்வொர்க் வழங்குநருக்கான தவறான பயன்பாட்டு அறிக்கையுடன் இணைக்க.',
    'Points' => 'புள்ளிகள்',
    'Verdict' => 'தீர்ப்பு',
    'Why' => 'ஏன்',
    'User / e-mail' => 'பயனர் / மின்னஞ்சல்',
    'Bot' => 'பாட்',
    'Doubtful' => 'சந்தேகத்திற்குரியது',
    'No suspicious attempts yet.' => 'இன்னும் சந்தேகத்திற்குரிய முயற்சிகள் இல்லை.',
    'The shield is off.' => 'கேடயம் அணைக்கப்பட்டுள்ளது.',
    'Invalid address.' => 'செல்லாத முகவரி.',
    'Automatic: %d bot attempts in 24 h' => 'தானியங்கி: 24 மணி நேரத்தில் %d பாட் முயற்சிகள்',
    'Ab insomni custodita dracone. Open-source security by Notorius Vision (OPNV Systems · OPNV SOLΞ): anti-bot shield without captchas, e-mail confirmation of forms and sign-ups, two-step login, firewall and site mail (SMTP).' => 'Ab insomni custodita dracone. Notorius Vision (OPNV Systems · OPNV SOLΞ) வழங்கும் திறந்த மூலப் பாதுகாப்பு: கேப்ட்சா இல்லாத பாட் எதிர்ப்புக் கேடயம், படிவங்கள் மற்றும் பதிவுகளின் மின்னஞ்சல் உறுதிப்படுத்தல், இரண்டு-படி உள்நுழைவு, ஃபயர்வால் மற்றும் தள மின்னஞ்சல் (SMTP).',
    'Ab insomni custodita dracone. Open-source security by Notorius Vision (OPNV Systems · OPNV SOLΞ): anti-bot shield without captchas, e-mail confirmation of forms and sign-ups, two-step login, firewall, anti-copy and site mail (SMTP).' => 'Ab insomni custodita dracone. Notorius Vision (OPNV Systems · OPNV SOLΞ) வழங்கும் திறந்த மூலப் பாதுகாப்பு: கேப்ட்சா இல்லாத பாட் எதிர்ப்புக் கேடயம், படிவங்கள் மற்றும் பதிவுகளின் மின்னஞ்சல் உறுதிப்படுத்தல், இரண்டு-படி உள்நுழைவு, ஃபயர்வால், நகல் எதிர்ப்பு மற்றும் தள மின்னஞ்சல் (SMTP).',
    'Anti-copy' => 'நகல் எதிர்ப்பு',
    'Makes it harder to copy the whole site in one go, without getting in the way of visitors or search engines. People logged in and the addresses an administrator used are never limited. Start with "Log only" for a few days and look at the list below.' => 'பார்வையாளர்களுக்கோ தேடுபொறிகளுக்கோ இடையூறு இல்லாமல், முழுத் தளத்தையும் ஒரே நேரத்தில் நகலெடுப்பதைக் கடினமாக்குகிறது. உள்நுழைந்தவர்களும் நிர்வாகி பயன்படுத்திய முகவரிகளும் ஒருபோதும் கட்டுப்படுத்தப்படுவதில்லை. சில நாட்கள் "பதிவு மட்டும்"-இல் தொடங்கி கீழே உள்ள பட்டியலைப் பாருங்கள்.',
    'Off' => 'அணை',
    'Log only: write down what it would stop, without stopping anything' => 'பதிவு மட்டும்: நிறுத்தக்கூடியதை எழுதிவைக்கும், எதையும் நிறுத்தாது',
    'Content API' => 'உள்ளடக்க API',
    'WordPress publishes every post, page and image as JSON at /wp-json/wp/v2/, which lets anyone download the whole site in a few requests. This closes those reads to anonymous visitors; the pages themselves stay public.' => 'WordPress ஒவ்வொரு இடுகை, பக்கம், படத்தையும் /wp-json/wp/v2/-இல் JSON ஆக வெளியிடுகிறது; இதனால் எவரும் சில கோரிக்கைகளில் முழுத் தளத்தையும் பதிவிறக்கலாம். இது அநாமதேயப் பார்வையாளர்களுக்கு அந்த வாசிப்புகளை மூடுகிறது; பக்கங்கள் பொதுவாகவே இருக்கும்.',
    'Routes that stay open' => 'திறந்தே இருக்கும் வழிகள்',
    'One per line, for example /wp/v2/posts if your theme loads more posts with JavaScript. The log below shows which routes visitors really use. Other APIs (forms, shop, embeds) are never affected.' => 'ஒரு வரிக்கு ஒன்று, உதாரணமாக உங்கள் தீம் JavaScript மூலம் கூடுதல் இடுகைகளை ஏற்றினால் /wp/v2/posts. பார்வையாளர்கள் உண்மையில் எந்த வழிகளைப் பயன்படுத்துகிறார்கள் என்பதைக் கீழே உள்ள பதிவு காட்டும். பிற API-கள் (படிவங்கள், கடை, உட்பொதிவுகள்) ஒருபோதும் பாதிக்கப்படாது.',
    'Pace' => 'வேகம்',
    'More pages per minute than a person reads get "429 Too many requests" for the rest of that minute. Google, Bing, Apple and Yandex are recognised by their reverse DNS and never limited; a program that only pretends to be them is.' => 'ஒரு மனிதர் படிப்பதைவிட நிமிடத்திற்கு அதிகமான பக்கங்கள் கேட்டால், அந்த நிமிடத்தின் மீதிக்கு "429 Too many requests" கிடைக்கும். Google, Bing, Apple, Yandex ஆகியவை தலைகீழ் DNS மூலம் அடையாளம் காணப்பட்டு ஒருபோதும் கட்டுப்படுத்தப்படுவதில்லை; அவர்களாக நடிக்கும் நிரல் மட்டும் கட்டுப்படுத்தப்படும்.',
    'Pages per minute from one address' => 'ஒரு முகவரியிலிருந்து நிமிடத்திற்குப் பக்கங்கள்',
    'Pages per minute from one network (the 256 addresses around it)' => 'ஒரு நெட்வொர்க்கிலிருந்து நிமிடத்திற்குப் பக்கங்கள் (அதைச் சுற்றியுள்ள 256 முகவரிகள்)',
    'Only requests that reach WordPress count: images, styles and pages served by a cache do not. Each counted request writes two small counters, so on a very busy site without an object cache keep this off or in log mode.' => 'WordPress-ஐ அடையும் கோரிக்கைகள் மட்டுமே கணக்கிடப்படும்: கேஷிலிருந்து வழங்கப்படும் படங்கள், ஸ்டைல்கள், பக்கங்கள் அல்ல. கணக்கிடப்படும் ஒவ்வொரு கோரிக்கையும் இரண்டு சிறிய எண்ணிகளை எழுதும்; எனவே ஆப்ஜெக்ட் கேஷ் இல்லாத மிகவும் பரபரப்பான தளத்தில் இதை அணைத்தோ பதிவு முறையிலோ வைக்கவும்.',
    'content API' => 'உள்ளடக்க API',
    'too fast, one address' => 'மிக வேகமாக, ஒரு முகவரி',
    'too fast, one network' => 'மிக வேகமாக, ஒரு நெட்வொர்க்',
    'Recent' => 'சமீபத்தியவை',
    'Browser' => 'உலாவி',
    'Nothing recorded yet.' => 'இன்னும் எதுவும் பதிவாகவில்லை.',
    'This content is not available through the API.' => 'இந்த உள்ளடக்கம் API வழியாகக் கிடைக்காது.',
    'Overview' => 'மேலோட்டம்',
    'Open source (GPL)' => 'திறந்த மூலம் (GPL)',
    'On' => 'இயக்கத்தில்',
    'Log only' => 'பதிவு மட்டும்',
    'Everything Draco Insomnis protects on this site, at a glance. Each module can be switched on and off on its own screen.' => 'இந்தத் தளத்தில் Draco Insomnis பாதுகாக்கும் அனைத்தும், ஒரே பார்வையில். ஒவ்வொரு தொகுதியையும் அதன் சொந்தத் திரையில் இயக்கலாம், அணைக்கலாம்.',
    'bots stopped in sign-ups' => 'பதிவுகளில் நிறுத்தப்பட்ட பாட்கள்',
    'submissions checked by e-mail' => 'மின்னஞ்சல் மூலம் சரிபார்க்கப்பட்ட அனுப்புதல்கள்',
    'attacks seen by the firewall' => 'ஃபயர்வால் கண்ட தாக்குதல்கள்',
    'copy attempts recorded' => 'பதிவான நகல் முயற்சிகள்',
    'Last 7 days.' => 'கடந்த 7 நாட்கள்.',
    '%d blocked addresses or e-mails right now' => 'இப்போது %d முகவரிகள் அல்லது மின்னஞ்சல்கள் தடுக்கப்பட்டுள்ளன',
    'Fake sign-ups are answered "done" and kept as evidence.' => 'போலிப் பதிவுகளுக்கு "முடிந்தது" எனப் பதில் தரப்பட்டு சான்றாக வைக்கப்படும்.',
    '%d waiting for their sender to confirm' => '%d அனுப்புநர் உறுதிப்படுத்தலுக்காகக் காத்திருக்கின்றன',
    'On without SMTP: confirmations may not arrive.' => 'SMTP இல்லாமல் இயக்கத்தில்: உறுதிப்படுத்தல்கள் வராமல் போகலாம்.',
    'Messages, comments and new accounts wait for an e-mail confirmation.' => 'செய்திகள், கருத்துகள், புதிய கணக்குகள் மின்னஞ்சல் உறுதிப்படுத்தலுக்காகக் காத்திருக்கும்.',
    'Only the password is asked for.' => 'கடவுச்சொல் மட்டுமே கேட்கப்படும்.',
    'Trusted devices: 7 days without a code.' => 'நம்பகச் சாதனங்கள்: 7 நாட்கள் குறியீடு இல்லாமல்.',
    'A code at every login.' => 'ஒவ்வொரு உள்நுழைவிலும் ஒரு குறியீடு.',
    'Stopping attacks.' => 'தாக்குதல்களை நிறுத்துகிறது.',
    'Recording attacks without stopping them.' => 'தாக்குதல்களை நிறுத்தாமல் பதிவு செய்கிறது.',
    'No request is inspected.' => 'எந்தக் கோரிக்கையும் சோதிக்கப்படுவதில்லை.',
    'User list hidden, failed logins limited, XML-RPC tamed.' => 'பயனர் பட்டியல் மறைக்கப்பட்டது, தோல்வியுற்ற உள்நுழைவுகள் கட்டுப்படுத்தப்பட்டன, XML-RPC அடக்கப்பட்டது.',
    'Content API for anonymous visitors and pages per minute.' => 'அநாமதேயப் பார்வையாளர்களுக்கான உள்ளடக்க API மற்றும் நிமிடத்திற்குப் பக்கங்கள்.',
    'Verified search engines are never limited.' => 'சரிபார்க்கப்பட்ட தேடுபொறிகள் ஒருபோதும் கட்டுப்படுத்தப்படுவதில்லை.',
    'Sending as %s' => '%s ஆக அனுப்புகிறது',
    'Login codes and confirmations depend on it.' => 'உள்நுழைவுக் குறியீடுகளும் உறுதிப்படுத்தல்களும் இதைச் சார்ந்துள்ளன.',
    'Checklist' => 'சரிபார்ப்புப் பட்டியல்',
    'What makes the biggest difference, in order.' => 'மிகப் பெரிய வேறுபாட்டை உண்டாக்குபவை, வரிசைப்படி.',
    'Site mail goes out through a real mailbox' => 'தள மின்னஞ்சல் ஓர் உண்மையான அஞ்சல்பெட்டி வழியாகச் செல்கிறது',
    'The anti-bot shield protects sign-ups' => 'பாட் எதிர்ப்புக் கேடயம் பதிவுகளைப் பாதுகாக்கிறது',
    'Forms and sign-ups are confirmed by e-mail' => 'படிவங்களும் பதிவுகளும் மின்னஞ்சல் மூலம் உறுதிப்படுத்தப்படுகின்றன',
    'Administrators log in with a code by e-mail' => 'நிர்வாகிகள் மின்னஞ்சல் குறியீட்டுடன் உள்நுழைகிறார்கள்',
    'You have a recovery e-mail' => 'உங்களுக்கு மீட்பு மின்னஞ்சல் உள்ளது',
    'The firewall blocks attacks (switch it from "Log only" once you have looked at what it records)' => 'ஃபயர்வால் தாக்குதல்களைத் தடுக்கிறது (அது பதிவு செய்வதைப் பார்த்த பின் "பதிவு மட்டும்"-இலிருந்து மாற்றவும்)',
    'The firewall is on' => 'ஃபயர்வால் இயக்கத்தில் உள்ளது',
    'Set it up' => 'அமை',
    'Administrators enter a code by e-mail.' => 'நிர்வாகிகள் மின்னஞ்சலில் வந்த குறியீட்டை உள்ளிடுவார்கள்.',
    'Everyone who edits content enters a code by e-mail.' => 'உள்ளடக்கத்தைத் திருத்தும் அனைவரும் மின்னஞ்சலில் வந்த குறியீட்டை உள்ளிடுவார்கள்.',
    'Every user enters a code by e-mail.' => 'அனைத்துப் பயனர்களும் மின்னஞ்சலில் வந்த குறியீட்டை உள்ளிடுவார்கள்.',
    'Nothing is checked.' => 'எதுவும் சோதிக்கப்படுவதில்லை.',
    'Writes down what it would stop, without stopping it.' => 'நிறுத்தக்கூடியதை நிறுத்தாமல் எழுதிவைக்கும்.',
    'Stops it, and writes it down.' => 'நிறுத்தும், எழுதிவைக்கும்.',
    'Writes down what it would stop, without stopping it. Start here for a few days.' => 'நிறுத்தக்கூடியதை நிறுத்தாமல் எழுதிவைக்கும். முதல் சில நாட்கள் இங்கிருந்து தொடங்குங்கள்.',
    'Stops those requests. Five in 10 minutes put the address on the block list for 7 days.' => 'அந்தக் கோரிக்கைகளை நிறுத்தும். 10 நிமிடங்களில் ஐந்து முறை நடந்தால் அந்த முகவரி 7 நாட்களுக்குத் தடைப் பட்டியலில் சேரும்.',
    'Contact Form 7, WPForms, Elementor, Divi, RealHomes, comments and new accounts.' => 'Contact Form 7, WPForms, Elementor, Divi, RealHomes, கருத்துகள் மற்றும் புதிய கணக்குகள்.',
    'The sender gets an e-mail with a button; nothing is delivered until it is pressed.' => 'அனுப்புநருக்கு ஒரு பொத்தானுடன் மின்னஞ்சல் வரும்; அது அழுத்தப்படும் வரை எதுவும் வழங்கப்படாது.',
    'Missing' => 'இல்லை',
    'SMTP' => 'SMTP',
    'Choose your provider and the server, encryption and port fill themselves in.' => 'உங்கள் வழங்குநரைத் தேர்ந்தெடுத்தால் சர்வர், குறியாக்கம், போர்ட் தானாக நிரம்பும்.',
    'Saved' => 'சேமிக்கப்பட்டது',
    'Passed' => 'தேர்ச்சி',
    'WordPress, WooCommerce and RealHomes sign-up forms.' => 'WordPress, WooCommerce மற்றும் RealHomes பதிவுப் படிவங்கள்.',
    'A hidden trap field and a signed page stamp: people never solve puzzles.' => 'மறைக்கப்பட்ட பொறிப் புலமும் கையொப்பமிட்ட பக்க முத்திரையும்: மனிதர்கள் ஒருபோதும் புதிர்களைத் தீர்க்க வேண்டியதில்லை.',
    'Never an administrator, nor your own address.' => 'ஒருபோதும் நிர்வாகி அல்ல, உங்கள் சொந்த முகவரியும் அல்ல.',
    'Active: %d' => 'செயலில்: %d',
    'The header is ignored: this connection (%s) does not come from Cloudflare or from a trusted proxy. If your proxy is on the internet, add its addresses below.' => 'தலைப்பு புறக்கணிக்கப்பட்டது: இந்த இணைப்பு (%s) Cloudflare-இலிருந்தோ நம்பகமான ப்ராக்ஸியிலிருந்தோ வரவில்லை. உங்கள் ப்ராக்ஸி இணையத்தில் இருந்தால், அதன் முகவரிகளைக் கீழே சேர்க்கவும்.',
    'Trusted proxies (one per line, e.g. 203.0.113.10 or 203.0.113.0/24; empty = this server and private networks)' => 'நம்பகமான ப்ராக்ஸிகள் (ஒரு வரிக்கு ஒன்று, உ.தா. 203.0.113.10 அல்லது 203.0.113.0/24; காலி = இந்த சர்வர் மற்றும் தனியார் நெட்வொர்க்குகள்)',
    'Forever' => 'என்றென்றும்',
    'IP or range (e.g. 203.0.113.0/24)' => 'IP அல்லது வரம்பு (உ.தா. 203.0.113.0/24)',
    'Range' => 'வரம்பு',
    'Allowed' => 'அனுமதிக்கப்பட்டது',
    'Your e-mail' => 'உங்கள் மின்னஞ்சல்',
    'What were you doing?' => 'நீங்கள் என்ன செய்துகொண்டிருந்தீர்கள்?',
    'Ask for a review' => 'மறுபரிசீலனை கேள்',
    '[%s] Someone asks you to review a firewall block' => '[%s] ஃபயர்வால் தடையை மறுபரிசீலிக்க ஒருவர் கேட்கிறார்',
    'A visitor stopped by the firewall asks for a review. Open the Firewall screen to let them through or not:' => 'ஃபயர்வால் நிறுத்திய ஒரு பார்வையாளர் மறுபரிசீலனை கேட்கிறார். அவரை அனுமதிக்க வேண்டுமா என முடிவெடுக்க ஃபயர்வால் திரையைத் திறக்கவும்:',
    'Request sent' => 'கோரிக்கை அனுப்பப்பட்டது',
    'Thank you. The owner of the site will look at it and, if it was a mistake, let you through.' => 'நன்றி. தள உரிமையாளர் இதைப் பார்த்து, தவறாக இருந்தால் உங்களை அனுமதிப்பார்.',
    'Review: %s' => 'மறுபரிசீலனை: %s',
    'This request was stopped for security reasons. If you think this is a mistake, tell the owner of the site what you were doing:' => 'பாதுகாப்புக் காரணங்களுக்காக இந்தக் கோரிக்கை நிறுத்தப்பட்டது. இது தவறு என நினைத்தால், நீங்கள் என்ன செய்துகொண்டிருந்தீர்கள் என்பதைத் தள உரிமையாளரிடம் சொல்லுங்கள்:',
    'The firewall is off: switch it on and save, then test again.' => 'ஃபயர்வால் அணைக்கப்பட்டுள்ளது: இயக்கி, சேமித்து, மீண்டும் சோதிக்கவும்.',
    'The test could not reach the site from the server itself (some hostings do not allow it). The firewall may still work: look at "Recent attacks".' => 'சோதனை சர்வரிலிருந்தே தளத்தை அடைய முடியவில்லை (சில ஹோஸ்டிங்குகள் அனுமதிப்பதில்லை). ஃபயர்வால் இன்னும் வேலை செய்யக்கூடும்: "சமீபத்திய தாக்குதல்கள்"-ஐப் பாருங்கள்.',
    'The test was stopped before it reached WordPress, by the hosting\'s own firewall. Good: two layers.' => 'சோதனை WordPress-ஐ அடைவதற்கு முன்பே ஹோஸ்டிங்கின் சொந்த ஃபயர்வாலால் நிறுத்தப்பட்டது. நல்லது: இரண்டு அடுக்குகள்.',
    'The test attack was not recognised. Please report it to Draco Insomnis.' => 'சோதனைத் தாக்குதல் அடையாளம் காணப்படவில்லை. தயவுசெய்து Draco Insomnis-க்குத் தெரிவிக்கவும்.',
    'Works: a database injection was recognised and blocked (403).' => 'வேலை செய்கிறது: ஒரு தரவுத்தள ஊடுருவல் அடையாளம் காணப்பட்டுத் தடுக்கப்பட்டது (403).',
    'Works: a database injection was recognised. In "Log only" it is written down but not stopped; switch to "Block" when you are ready.' => 'வேலை செய்கிறது: ஒரு தரவுத்தள ஊடுருவல் அடையாளம் காணப்பட்டது. "பதிவு மட்டும்"-இல் அது எழுதிவைக்கப்படும், நிறுத்தப்படாது; தயாரானதும் "தடு"-க்கு மாறவும்.',
    'Test the firewall' => 'ஃபயர்வாலைச் சோதி',
    'Sends a harmless attack-shaped request to the site and tells you what happened. It is not logged.' => 'தளத்திற்குத் தாக்குதல் வடிவிலான தீங்கற்ற ஒரு கோரிக்கையை அனுப்பி என்ன நடந்தது என்று சொல்லும். இது பதிவு செய்யப்படாது.',
    '%1$d attacks seen, %2$d blocked.' => '%1$d தாக்குதல்கள் காணப்பட்டன, %2$d தடுக்கப்பட்டன.',
    'Last 7 days' => 'கடந்த 7 நாட்கள்',
    'Busiest addresses' => 'மிகவும் செயலில் உள்ள முகவரிகள்',
    'Waiting: %d' => 'காத்திருக்கின்றன: %d',
    'Review requests' => 'மறுபரிசீலனைக் கோரிக்கைகள்',
    'People the firewall stopped can ask from the block page. Let them through for a while if it was a mistake. Draco never writes to them: answer from your own mail if you want.' => 'ஃபயர்வால் நிறுத்தியவர்கள் தடைப் பக்கத்திலிருந்து கேட்கலாம். தவறாக இருந்தால் சிறிது காலம் அனுமதிக்கவும். Draco அவர்களுக்கு ஒருபோதும் எழுதாது: விரும்பினால் உங்கள் சொந்த மின்னஞ்சலிலிருந்து பதிலளிக்கவும்.',
    'Let through' => 'அனுமதி',
    'Denied' => 'மறுக்கப்பட்டது',
    'Attacker: blocked' => 'தாக்குபவர்: தடுக்கப்பட்டார்',
    '24 hours' => '24 மணி நேரம்',
    'Deny' => 'மறு',
    'Attacker' => 'தாக்குபவர்',
    'No requests.' => 'கோரிக்கைகள் இல்லை.',
    'country not allowed' => 'அனுமதிக்கப்படாத நாடு',
    'The country list could not be downloaded. The filter does nothing until it is there; try "Update the country list" later.' => 'நாடுகள் பட்டியலைப் பதிவிறக்க முடியவில்லை. அது வரும் வரை வடிகட்டி எதுவும் செய்யாது; பிறகு "நாடுகள் பட்டியலைப் புதுப்பி"-ஐ முயலவும்.',
    'Country list downloaded.' => 'நாடுகள் பட்டியல் பதிவிறக்கப்பட்டது.',
    'Countries' => 'நாடுகள்',
    'Most of your visitors may come from many countries, and an attacker changes country with a VPN. Filter only logging in, signing up and forms, and start with "Log only". Administrators, people you let through and search engines are never filtered.' => 'உங்கள் பார்வையாளர்கள் பல நாடுகளிலிருந்து வரலாம், தாக்குபவர் VPN மூலம் நாட்டை மாற்றுவார். உள்நுழைவு, பதிவு, படிவங்களை மட்டும் வடிகட்டி, "பதிவு மட்டும்"-இல் தொடங்குங்கள். நிர்வாகிகள், நீங்கள் அனுமதித்தவர்கள், தேடுபொறிகள் ஒருபோதும் வடிகட்டப்படுவதில்லை.',
    'Filter' => 'வடிகட்டி',
    'Refuse the countries listed' => 'பட்டியலில் உள்ள நாடுகளை மறு',
    'Only the countries listed' => 'பட்டியலில் உள்ள நாடுகள் மட்டும்',
    'Logging in, signing up and forms (recommended)' => 'உள்நுழைவு, பதிவு மற்றும் படிவங்கள் (பரிந்துரைக்கப்படுகிறது)',
    'The whole site' => 'முழுத் தளம்',
    'What to do' => 'என்ன செய்ய வேண்டும்',
    'Countries (two-letter codes, e.g. ES, FR, DE)' => 'நாடுகள் (இரண்டு எழுத்துக் குறியீடுகள், உ.தா. ES, FR, DE)',
    'Country list: not downloaded yet (it is downloaded when you switch the filter on).' => 'நாடுகள் பட்டியல்: இன்னும் பதிவிறக்கப்படவில்லை (வடிகட்டியை இயக்கும்போது பதிவிறக்கப்படும்).',
    'Country list of %s.' => '%s தேதியிட்ட நாடுகள் பட்டியல்.',
    'Update the country list' => 'நாடுகள் பட்டியலைப் புதுப்பி',
    'IP geolocation by %s (CC BY 4.0). Looked up on your own server: no address is sent anywhere.' => '%s வழங்கும் IP புவியிருப்பிடம் (CC BY 4.0). உங்கள் சொந்த சர்வரில் தேடப்படுகிறது: எந்த முகவரியும் எங்கும் அனுப்பப்படுவதில்லை.',
    'The password must have at least %d characters.' => 'கடவுச்சொல்லில் குறைந்தது %d எழுத்துகள் இருக்க வேண்டும்.',
    'This password appears in known data breaches, so attackers try it first. Please choose another one.' => 'இந்தக் கடவுச்சொல் தெரிந்த தரவுக் கசிவுகளில் உள்ளது, எனவே தாக்குபவர்கள் இதை முதலில் முயல்வார்கள். தயவுசெய்து வேறொன்றைத் தேர்ந்தெடுக்கவும்.',
    'Your password appears in known data breaches.' => 'உங்கள் கடவுச்சொல் தெரிந்த தரவுக் கசிவுகளில் உள்ளது.',
    'Attackers try those first. Change it now:' => 'தாக்குபவர்கள் அவற்றை முதலில் முயல்வார்கள். இப்போதே மாற்றவும்:',
    'Change my password' => 'என் கடவுச்சொல்லை மாற்று',
    'Passwords' => 'கடவுச்சொற்கள்',
    'Applied when someone chooses a password: profile, reset and WooCommerce sign-up. Existing passwords keep working.' => 'ஒருவர் கடவுச்சொல்லைத் தேர்ந்தெடுக்கும்போது பொருந்தும்: சுயவிவரம், மீட்டமைப்பு மற்றும் WooCommerce பதிவு. இருக்கும் கடவுச்சொற்கள் தொடர்ந்து வேலை செய்யும்.',
    'Minimum length' => 'குறைந்தபட்ச நீளம்',
    'No minimum (WordPress default)' => 'குறைந்தபட்சம் இல்லை (WordPress இயல்புநிலை)',
    '%d characters' => '%d எழுத்துகள்',
    'recommended' => 'பரிந்துரைக்கப்படுகிறது',
    'Refuse passwords that appear in known data breaches, and warn people who log in with one' => 'தெரிந்த கசிவுகளில் உள்ள கடவுச்சொற்களை மறுத்து, அத்தகைய கடவுச்சொல்லுடன் உள்நுழைபவர்களை எச்சரி',
    'Asks Have I Been Pwned with only the first 5 characters of the password\'s SHA-1: the password never leaves your site. If the service does not answer in 3 seconds, the password is accepted.' => 'கடவுச்சொல்லின் SHA-1-இன் முதல் 5 எழுத்துகளை மட்டும் வைத்து Have I Been Pwned-இடம் கேட்கிறது: கடவுச்சொல் உங்கள் தளத்தை விட்டு ஒருபோதும் வெளியேறாது. சேவை 3 வினாடிகளில் பதிலளிக்காவிட்டால், கடவுச்சொல் ஏற்கப்படும்.',
    'Send security headers on public pages (no sniffing of file types, no framing by other sites, less referrer data, no camera, microphone or location for embedded content)' => 'பொதுப் பக்கங்களில் பாதுகாப்புத் தலைப்புகளை அனுப்பு (கோப்பு வகையை ஊகிக்காது, பிற தளங்கள் சட்டமிட முடியாது, குறைந்த பரிந்துரையாளர் தரவு, உட்பொதித்த உள்ளடக்கத்திற்குக் கேமரா, மைக்ரோஃபோன், இருப்பிடம் இல்லை)',
    'Safe for almost every site. If another plugin or the server already sends one of them, Draco leaves it alone.' => 'கிட்டத்தட்ட எல்லாத் தளங்களுக்கும் பாதுகாப்பானது. வேறொரு செருகுநிரல் அல்லது சர்வர் ஏற்கனவே ஏதேனும் ஒன்றை அனுப்பினால், Draco அதைத் தொடாது.',
    'Force HTTPS in browsers for 6 months (HSTS)' => 'உலாவிகளில் 6 மாதங்களுக்கு HTTPS-ஐக் கட்டாயமாக்கு (HSTS)',
    'Only when the whole site works on HTTPS and will keep working: browsers remember it and refuse plain HTTP until it expires.' => 'முழுத் தளமும் HTTPS-இல் இயங்கி, தொடர்ந்து இயங்கும் என்றால் மட்டும்: உலாவிகள் இதை நினைவில் வைத்து, காலம் முடியும் வரை HTTP-ஐ மறுக்கும்.',
    'Abuse report sent. Replies will arrive at the administrator e-mail.' => 'தவறான பயன்பாட்டுப் புகார் அனுப்பப்பட்டது. பதில்கள் நிர்வாகியின் மின்னஞ்சலுக்கு வரும்.',
    'The abuse report could not be sent: WordPress could not deliver the e-mail. Check the site mail settings.' => 'தவறான பயன்பாட்டுப் புகாரை அனுப்ப முடியவில்லை: WordPress மின்னஞ்சலை வழங்க முடியவில்லை. தளத்தின் அஞ்சல் அமைப்புகளைச் சரிபார்க்கவும்.',
    'The abuse report was not sent: an address, subject and message are needed, and the limits (one per address every 30 days, 5 a day) must allow it.' => 'தவறான பயன்பாட்டுப் புகார் அனுப்பப்படவில்லை: முகவரி, தலைப்பு, செய்தி தேவை, மேலும் வரம்புகள் (ஒரு முகவரிக்கு 30 நாட்களுக்கு ஒன்று, நாளுக்கு 5) அனுமதிக்க வேண்டும்.',
    'Report' => 'புகாரளி',
    'Abuse report' => 'தவறான பயன்பாட்டுப் புகார்',
    'Tell the network that owns the address what its machine did, so they can look at it. Most attacking machines are compromised: their owners are victims too. Nothing is sent until you press Send.' => 'முகவரிக்கு உரிய நெட்வொர்க்கிடம் அதன் இயந்திரம் என்ன செய்தது என்று சொல்லுங்கள், அவர்கள் சரிபார்க்கலாம். தாக்கும் பெரும்பாலான இயந்திரங்கள் கைப்பற்றப்பட்டவை: அவற்றின் உரிமையாளர்களும் பாதிக்கப்பட்டவர்களே. நீங்கள் அனுப்பு என்பதை அழுத்தும் வரை எதுவும் அனுப்பப்படாது.',
    'There is no evidence from this address.' => 'இந்த முகவரியிலிருந்து எந்தச் சான்றும் இல்லை.',
    'Back' => 'பின்செல்',
    'Not now' => 'இப்போது வேண்டாம்',
    'The registry gave no abuse contact (%s). Write the address yourself if you know it.' => 'பதிவகம் தவறான பயன்பாட்டுத் தொடர்பு எதையும் தரவில்லை (%s). முகவரி தெரிந்தால் நீங்களே எழுதுங்கள்.',
    'Not sent now: %s.' => 'இப்போது அனுப்பப்படவில்லை: %s.',
    'To (abuse contact of the network)' => 'பெறுநர் (நெட்வொர்க்கின் தவறான பயன்பாட்டுத் தொடர்பு)',
    'Message (in English, which abuse desks read; edit anything you like)' => 'செய்தி (ஆங்கிலத்தில், தவறான பயன்பாட்டுக் குழுக்கள் படிப்பது; விரும்பியதை மாற்றலாம்)',
    'Replies go to %s. Never more than one report per address every 30 days, nor more than 5 a day.' => 'பதில்கள் %s க்குச் செல்லும். ஒரு முகவரிக்கு 30 நாட்களில் ஒன்றுக்கு மேல் புகார் இல்லை, நாளுக்கு 5 க்கு மேல் இல்லை.',
    'Send the report' => 'புகாரை அனுப்பு',
    'Abuse reports sent' => 'அனுப்பிய தவறான பயன்பாட்டுப் புகார்கள்',
    'The last 20. Replies arrive at the administrator e-mail.' => 'கடைசி 20. பதில்கள் நிர்வாகியின் மின்னஞ்சலுக்கு வரும்.',
    'Accounts that can change the site' => 'தளத்தை மாற்றக்கூடிய கணக்குகள்',
    'Administrators, editors and shop managers only work once you approved them, so an account created by an attack cannot log in. If the site e-mail, its address, the default role or open registration change without you, they are all paused until you confirm from your e-mail.' => 'நிர்வாகிகள், தொகுப்பாளர்கள், கடை மேலாளர்கள் நீங்கள் அங்கீகரித்த பின்னரே செயல்படுவார்கள், எனவே தாக்குதலால் உருவான கணக்கு உள்நுழைய முடியாது. தளத்தின் மின்னஞ்சல், அதன் முகவரி, இயல்புநிலைப் பங்கு அல்லது திறந்த பதிவு நீங்கள் இல்லாமல் மாறினால், உங்கள் மின்னஞ்சலிலிருந்து உறுதிசெய்யும் வரை அனைத்தும் இடைநிறுத்தப்படும்.',
    'Only approved accounts can change the site' => 'அங்கீகரிக்கப்பட்ட கணக்குகள் மட்டுமே தளத்தை மாற்ற முடியும்',
    'Switching it on approves you and keeps your e-mail for confirmations. Other privileged accounts wait until you approve them below.' => 'இதை இயக்கினால் நீங்கள் அங்கீகரிக்கப்படுவீர்கள், உறுதிப்படுத்தல்களுக்காக உங்கள் மின்னஞ்சல் சேமிக்கப்படும். சிறப்புரிமை கொண்ட பிற கணக்குகள் நீங்கள் கீழே அங்கீகரிக்கும் வரை காத்திருக்கும்.',
    'Paused: a sensitive setting changed. The confirmation link was sent to the e-mail kept when the lock was switched on.' => 'இடைநிறுத்தப்பட்டது: ஒரு முக்கிய அமைப்பு மாறியது. பூட்டை இயக்கியபோது சேமித்த மின்னஞ்சலுக்கு உறுதிப்படுத்தல் இணைப்பு அனுப்பப்பட்டது.',
    'Confirmations go to %s.' => 'உறுதிப்படுத்தல்கள் %s க்குச் செல்லும்.',
    'Role' => 'பங்கு',
    'State' => 'நிலை',
    'Approved' => 'அங்கீகரிக்கப்பட்டது',
    'Waiting for approval' => 'அங்கீகாரத்திற்காகக் காத்திருக்கிறது',
    'Withdraw approval' => 'அங்கீகாரத்தைத் திரும்பப் பெறு',
    'Approve' => 'அங்கீகரி',
    'Accounts created from the command line (WP-CLI) also wait for approval. Locked out? Add define(\'DRACO_LOCK_OFF\', true); to wp-config.php, log in, fix it and remove the line.' => 'கட்டளை வரியில் (WP-CLI) உருவாக்கிய கணக்குகளும் அங்கீகாரத்திற்காகக் காத்திருக்கும். உள்ளே நுழைய முடியவில்லையா? wp-config.php இல் define(\'DRACO_LOCK_OFF\', true); சேர்த்து, உள்நுழைந்து, சரிசெய்து, அந்த வரியை நீக்குங்கள்.',
    'DRACO_LOCK_OFF is set in wp-config.php: accounts that can change the site are not checked. Remove that line once you are back in.' => 'wp-config.php இல் DRACO_LOCK_OFF அமைக்கப்பட்டுள்ளது: தளத்தை மாற்றக்கூடிய கணக்குகள் சரிபார்க்கப்படுவதில்லை. மீண்டும் உள்ளே வந்ததும் அந்த வரியை நீக்குங்கள்.',
    'Not available on multisite networks yet.' => 'பல்தள நெட்வொர்க்குகளில் இன்னும் கிடைக்கவில்லை.',
    'Accounts that can change this site are paused because a sensitive setting changed. The site owner has been sent an e-mail to confirm.' => 'ஒரு முக்கிய அமைப்பு மாறியதால் இந்தத் தளத்தை மாற்றக்கூடிய கணக்குகள் இடைநிறுத்தப்பட்டுள்ளன. உறுதிசெய்ய தள உரிமையாளருக்கு மின்னஞ்சல் அனுப்பப்பட்டது.',
    'This account can change the site, so it has to be approved by the site owner first. The owner has been sent an e-mail.' => 'இந்தக் கணக்கு தளத்தை மாற்ற முடியும், எனவே முதலில் தள உரிமையாளர் அதை அங்கீகரிக்க வேண்டும். உரிமையாளருக்கு மின்னஞ்சல் அனுப்பப்பட்டது.',
    'Privileged accounts' => 'சிறப்புரிமை கொண்ட கணக்குகள்',
    'This link has expired or was already used.' => 'இந்த இணைப்பு காலாவதியானது அல்லது ஏற்கெனவே பயன்படுத்தப்பட்டது.',
    'Done. The account can log in now.' => 'முடிந்தது. இப்போது இந்தக் கணக்கு உள்நுழையலாம்.',
    'A sensitive setting of the site changed (its e-mail, its address, the default role or open registration) and every account that can change the site was paused. Confirm only if you or someone you trust made that change.' => 'தளத்தின் ஒரு முக்கிய அமைப்பு (அதன் மின்னஞ்சல், முகவரி, இயல்புநிலைப் பங்கு அல்லது திறந்த பதிவு) மாறியது, தளத்தை மாற்றக்கூடிய ஒவ்வொரு கணக்கும் இடைநிறுத்தப்பட்டது. அந்த மாற்றத்தை நீங்களோ நீங்கள் நம்பும் ஒருவரோ செய்திருந்தால் மட்டும் உறுதிசெய்யுங்கள்.',
    'The account %1$s (%2$s) can change the site and is waiting for your approval. Approve it only if you know who it belongs to.' => '%1$s (%2$s) கணக்கு தளத்தை மாற்ற முடியும், உங்கள் அங்கீகாரத்திற்காகக் காத்திருக்கிறது. அது யாருடையது என்று தெரிந்தால் மட்டும் அங்கீகரியுங்கள்.',
    '[%s] Accounts that can change the site were paused' => '[%s] தளத்தை மாற்றக்கூடிய கணக்குகள் இடைநிறுத்தப்பட்டன',
    'A sensitive setting of your site changed (its e-mail, its address, the default role or open registration) without an approved administrator doing it, so every account that can change the site was paused. If you made the change, confirm it here. If not, your site may be compromised: do not confirm, and ask whoever manages your hosting for help.' => 'அங்கீகரிக்கப்பட்ட நிர்வாகி செய்யாமலேயே உங்கள் தளத்தின் ஒரு முக்கிய அமைப்பு (அதன் மின்னஞ்சல், முகவரி, இயல்புநிலைப் பங்கு அல்லது திறந்த பதிவு) மாறியது, எனவே தளத்தை மாற்றக்கூடிய ஒவ்வொரு கணக்கும் இடைநிறுத்தப்பட்டது. மாற்றத்தை நீங்கள் செய்திருந்தால், இங்கே உறுதிசெய்யுங்கள். இல்லையெனில் உங்கள் தளம் கைப்பற்றப்பட்டிருக்கலாம்: உறுதிசெய்ய வேண்டாம், உங்கள் ஹோஸ்டிங்கை நிர்வகிப்பவரிடம் உதவி கேளுங்கள்.',
    '[%s] An account is waiting for your approval' => '[%s] ஒரு கணக்கு உங்கள் அங்கீகாரத்திற்காகக் காத்திருக்கிறது',
    'The account %1$s (%2$s) can change your site and tried to log in. It was not approved by you. If you know who it belongs to, approve it here. If not, do not approve it: someone may have created it to take over your site.' => '%1$s (%2$s) கணக்கு உங்கள் தளத்தை மாற்ற முடியும், அது உள்நுழைய முயன்றது. நீங்கள் அதை அங்கீகரிக்கவில்லை. அது யாருடையது என்று தெரிந்தால், இங்கே அங்கீகரியுங்கள். இல்லையெனில் அங்கீகரிக்க வேண்டாம்: உங்கள் தளத்தைக் கைப்பற்ற யாரோ அதை உருவாக்கியிருக்கலாம்.',
    'The link works once and expires in 24 hours.' => 'இணைப்பு ஒருமுறை மட்டுமே செயல்படும், 24 மணி நேரத்தில் காலாவதியாகும்.',
    'Draco Insomnis' => 'Draco Insomnis',
    'https://github.com/fermatacordis-create/draco-insomnis' => 'https://github.com/fermatacordis-create/draco-insomnis',
    'Notorius Vision · OPNV Systems' => 'Notorius Vision · OPNV Systems',
    'https://notoriusvision.com' => 'https://notoriusvision.com',
    'Trusted devices skip only the verification code. Administrator co-sign approval remains mandatory.' => 'நம்பகச் சாதனங்கள் சரிபார்ப்புக் குறியீட்டை மட்டுமே தவிர்க்கும். நிர்வாகியின் இணை ஒப்புதல் கட்டாயமாகவே இருக்கும்.',
    'Recovery e-mails configured' => 'மீட்பு மின்னஞ்சல்கள் அமைக்கப்பட்டன',
    'Second administrator approval' => 'இரண்டாம் நிர்வாகியின் ஒப்புதல்',
    'Trusted devices' => 'நம்பகச் சாதனங்கள்',
    'Allow the microphone for this site (OPNV Accessibility voice commands)' => 'இந்தத் தளத்திற்கு மைக்ரோஃபோனை அனுமதி (OPNV அணுகல்தன்மை குரல் கட்டளைகள்)',
    'Only when security headers are on. Reading aloud never needs the microphone. Voice commands do: this sets microphone=(self) so this site may ask for it, while camera, location and embeds stay blocked.' => 'பாதுகாப்புத் தலைப்புகள் இயக்கத்தில் இருக்கும்போது மட்டும். உரக்கப் படிக்க மைக்ரோஃபோன் ஒருபோதும் தேவையில்லை. குரல் கட்டளைகளுக்குத் தேவை: இது microphone=(self) என அமைத்து இந்தத் தளம் அதைக் கேட்க அனுமதிக்கிறது; கேமரா, இருப்பிடம், உட்பொதிப்புகள் தடுக்கப்பட்டே இருக்கும்.',
    'Malicious links (URLhaus)' => 'தீங்கிழைக்கும் இணைப்புகள் (URLhaus)',
    'Links in comments and contact forms are checked against URLhaus, the list of malware sites kept by abuse.ch. The list is downloaded twice a day with your own key and checked on this server: nothing your visitors write is sent anywhere. A comment with a listed link goes to spam; a contact message with one is not delivered.' => 'கருத்துகள் மற்றும் தொடர்புப் படிவங்களில் உள்ள இணைப்புகள் abuse.ch பராமரிக்கும் தீம்பொருள் தளப் பட்டியலான URLhaus உடன் ஒப்பிடப்படுகின்றன. பட்டியல் உங்கள் சொந்த விசையுடன் நாளுக்கு இருமுறை பதிவிறக்கப்பட்டு இந்தச் சேவையகத்திலேயே சரிபார்க்கப்படுகிறது: உங்கள் பார்வையாளர்கள் எழுதுவது எதுவும் எங்கும் அனுப்பப்படாது. பட்டியலிலுள்ள இணைப்பு கொண்ட கருத்து ஸ்பேமுக்குச் செல்லும்; அத்தகைய இணைப்பு கொண்ட தொடர்புச் செய்தி வழங்கப்படாது.',
    'Free use only for non-profit websites; for commercial use, a Spamhaus subscription.' => 'இலாப நோக்கற்ற இணையதளங்களுக்கு மட்டும் இலவசம்; வணிகப் பயன்பாட்டுக்கு Spamhaus சந்தா தேவை.',
    'That is what the abuse.ch terms of use say for URLhaus.' => 'URLhaus-க்கான abuse.ch பயன்பாட்டு விதிமுறைகள் இதையே சொல்கின்றன.',
    'Terms of use' => 'பயன்பாட்டு விதிமுறைகள்',
    'Spamhaus subscription' => 'Spamhaus சந்தா',
    'To use it, create a free account at auth.abuse.ch, copy your Auth-Key and add this line to wp-config.php. The key stays there: it is never saved in the database or shown on any screen.' => 'இதைப் பயன்படுத்த auth.abuse.ch-இல் இலவசக் கணக்கை உருவாக்கி, உங்கள் Auth-Key-ஐ நகலெடுத்து, இந்த வரியை wp-config.php-இல் சேர்க்கவும். விசை அங்கேயே இருக்கும்: தரவுத்தளத்தில் சேமிக்கப்படவோ எந்தத் திரையிலும் காட்டப்படவோ மாட்டாது.',
    'your-key' => 'your-key',
    'Key found in wp-config.php.' => 'wp-config.php-இல் விசை கண்டறியப்பட்டது.',
    'Last download: %1$s, %2$d entries.' => 'கடைசிப் பதிவிறக்கம்: %1$s, %2$d பதிவுகள்.',
    'Last attempt failed: %s.' => 'கடைசி முயற்சி தோல்வியடைந்தது: %s.',
    'I confirm this website is non-profit, or has a Spamhaus subscription' => 'இந்த இணையதளம் இலாப நோக்கற்றது அல்லது Spamhaus சந்தா உள்ளது என உறுதிசெய்கிறேன்',
    'Check links in comments and contact forms' => 'கருத்துகள் மற்றும் தொடர்புப் படிவங்களில் உள்ள இணைப்புகளைச் சரிபார்',
    'Download the list now' => 'பட்டியலை இப்போது பதிவிறக்கு',
    'Recent submissions cleared. Blocked addresses stay on the block list.' => 'சமீபத்திய சமர்ப்பிப்புகள் அழிக்கப்பட்டன. தடுக்கப்பட்ட முகவரிகள் தடைப் பட்டியலில் இருக்கும்.',
    'Address unblocked.' => 'முகவரியின் தடை நீக்கப்பட்டது.',
    'Malicious links were not switched on: add your abuse.ch key to wp-config.php first.' => 'தீங்கிழைக்கும் இணைப்புச் சரிபார்ப்பு இயக்கப்படவில்லை: முதலில் உங்கள் abuse.ch விசையை wp-config.php-இல் சேர்க்கவும்.',
    'Malicious links were not switched on: confirm first that the site is non-profit or has a Spamhaus subscription.' => 'தீங்கிழைக்கும் இணைப்புச் சரிபார்ப்பு இயக்கப்படவில்லை: தளம் இலாப நோக்கற்றது அல்லது Spamhaus சந்தா உள்ளது என முதலில் உறுதிசெய்யவும்.',
    'URLhaus list downloaded: %d entries.' => 'URLhaus பட்டியல் பதிவிறக்கப்பட்டது: %d பதிவுகள்.',
    'The URLhaus list could not be downloaded (%s). Links are not checked until it is.' => 'URLhaus பட்டியலைப் பதிவிறக்க முடியவில்லை (%s). பதிவிறக்கப்படும் வரை இணைப்புகள் சரிபார்க்கப்படாது.',
    'Each submission is kept for 90 days, confirmed or not. "Block" works on any row — including after they confirm from their e-mail: confirming only proves the mailbox exists, not that it can be trusted. "Deliver now" lets a real submission through without waiting.' => 'ஒவ்வொரு சமர்ப்பிப்பும் உறுதிசெய்யப்பட்டாலும் இல்லாவிட்டாலும் 90 நாட்கள் வைக்கப்படும். "தடு" எந்த வரிசையிலும் வேலை செய்யும் — அவர்கள் மின்னஞ்சலில் உறுதிசெய்த பின்னரும்: உறுதிசெய்தல் அஞ்சல்பெட்டி இருப்பதை மட்டுமே நிரூபிக்கும், நம்பத்தகுந்தது என்பதை அல்ல. "இப்போதே அனுப்பு" உண்மையான சமர்ப்பிப்பைக் காத்திருக்காமல் அனுப்பும்.',
    'Clear all recent submissions from this list? Blocked addresses stay on the block list. This cannot be undone.' => 'இந்தப் பட்டியலின் சமீபத்திய சமர்ப்பிப்புகள் அனைத்தையும் அழிக்கவா? தடுக்கப்பட்ட முகவரிகள் தடைப் பட்டியலில் இருக்கும். இதைத் திரும்பப் பெற முடியாது.',
    'Clear list' => 'பட்டியலை அழி',
    'Block confirmed sender' => 'உறுதிசெய்யப்பட்ட அனுப்புநரைத் தடு',
    'DRACO_COSIGN_OFF is set in wp-config.php: a second administrator is not required to co-sign. Remove that line once you are back in.' => 'wp-config.php-இல் DRACO_COSIGN_OFF அமைக்கப்பட்டுள்ளது: இரண்டாம் நிர்வாகியின் இணை ஒப்புதல் தேவையில்லை. மீண்டும் உள்நுழைந்ததும் அந்த வரியை நீக்கவும்.',
    'Trusted devices skip only the verification code. A second administrator approval is still required when CoSign is enabled.' => 'நம்பகச் சாதனங்கள் சரிபார்ப்புக் குறியீட்டை மட்டுமே தவிர்க்கும். இணை ஒப்புதல் இயக்கத்தில் இருந்தால், இரண்டாம் நிர்வாகியின் ஒப்புதல் இன்னும் தேவை.',
    'Administrator co-sign' => 'நிர்வாகி இணை ஒப்புதல்',
    'A second administrator must approve this sign-in. The session belongs only to the first account.' => 'இந்த உள்நுழைவை இரண்டாம் நிர்வாகி ஒப்புக்கொள்ள வேண்டும். அமர்வு முதல் கணக்குக்கு மட்டுமே சொந்தமானது.',
    'Service accounts cannot be used for co-sign approval.' => 'சேவைக் கணக்குகளை இணை ஒப்புதலுக்குப் பயன்படுத்த முடியாது.',
    'Trust Device is not a trusted login: passwords A and B and co-sign stay mandatory; only the e-mail code may be skipped. Prefer a quiet approval account (Admin B) with its own mailbox, unused on the public site.' => '"சாதனத்தை நம்பு" என்பது நம்பக உள்நுழைவு அல்ல: கடவுச்சொற்கள் A, B மற்றும் இணை ஒப்புதல் கட்டாயம்; மின்னஞ்சல் குறியீட்டை மட்டுமே தவிர்க்கலாம். பொதுத் தளத்தில் பயன்படுத்தாத, சொந்த அஞ்சல்பெட்டி கொண்ட அமைதியான ஒப்புதல் கணக்கை (Admin B) விரும்பவும்.',
    'This account needs a second administrator to co-sign. Log in from %s.' => 'இந்தக் கணக்குக்கு இரண்டாம் நிர்வாகியின் இணை ஒப்புதல் தேவை. %s இலிருந்து உள்நுழையவும்.',
    'The co-signature step has expired. Log in again.' => 'இணை ஒப்புதல் படி காலாவதியானது. மீண்டும் உள்நுழையவும்.',
    'The co-signature could not be verified.' => 'இணை ஒப்புதலைச் சரிபார்க்க முடியவில்லை.',
    'A second administrator must co-sign before %s can finish logging in.' => '%s உள்நுழைவை முடிக்கும் முன் இரண்டாம் நிர்வாகி இணை ஒப்புதல் தர வேண்டும்.',
    'Administrator co-signature' => 'நிர்வாகியின் இணை ஒப்புதல்',
    'Co-signer username or e-mail' => 'இணை ஒப்புதலாளரின் பயனர்பெயர் அல்லது மின்னஞ்சல்',
    'Co-signer password' => 'இணை ஒப்புதலாளரின் கடவுச்சொல்',
    'Co-sign and continue' => 'ஒப்புதல் அளித்துத் தொடர்',
    'A recovery e-mail was removed from your account.' => 'உங்கள் கணக்கிலிருந்து ஒரு மீட்பு மின்னஞ்சல் நீக்கப்பட்டது.',
    'Your password has been reset. The next login code will go to your primary recovery e-mail.' => 'உங்கள் கடவுச்சொல் மீட்டமைக்கப்பட்டது. அடுத்த உள்நுழைவுக் குறியீடு உங்கள் முதன்மை மீட்பு மின்னஞ்சலுக்குச் செல்லும்.',
    'We have sent a code to that recovery address. Type it below to remove it.' => 'அந்த மீட்பு முகவரிக்கு ஒரு குறியீட்டை அனுப்பியுள்ளோம். அதை நீக்க, குறியீட்டைக் கீழே உள்ளிடவும்.',
    'Recovery e-mail removed.' => 'மீட்பு மின்னஞ்சல் நீக்கப்பட்டது.',
    'That address is already one of your recovery e-mails.' => 'அந்த முகவரி ஏற்கனவே உங்கள் மீட்பு மின்னஞ்சல்களில் ஒன்று.',
    'You already have three recovery e-mails. Remove one to add another.' => 'உங்களிடம் ஏற்கனவே மூன்று மீட்பு மின்னஞ்சல்கள் உள்ளன. மற்றொன்றைச் சேர்க்க ஒன்றை நீக்கவும்.',
    'You need at least one recovery e-mail while the login code is on.' => 'உள்நுழைவுக் குறியீடு இயக்கத்தில் இருக்கும்வரை குறைந்தது ஒரு மீட்பு மின்னஞ்சல் தேவை.',
    'Up to three mailboxes for your login code, like nested PUKs. Prefer providers different from your main e-mail (for example Gmail if the main one is on this site\'s domain).' => 'உங்கள் உள்நுழைவுக் குறியீட்டுக்கு அதிகபட்சம் மூன்று அஞ்சல்பெட்டிகள், காப்பு PUK போல. உங்கள் முதன்மை மின்னஞ்சலிலிருந்து வேறுபட்ட வழங்குநர்களை விரும்பவும் (உதாரணமாக முதன்மை முகவரி இந்தத் தளத்தின் டொமைனில் இருந்தால் Gmail).',
    'Recovery e-mails' => 'மீட்பு மின்னஞ்சல்கள்',
    'Slots in use: %d of 3' => 'பயன்பாட்டில் உள்ள இடங்கள்: 3-இல் %d',
    'Remove' => 'நீக்கு',
    'Primary recovery' => 'முதன்மை மீட்பு',
    'Replace with…' => 'இதனால் மாற்று…',
    'Replace' => 'மாற்று',
    'Add recovery e-mail' => 'மீட்பு மின்னஞ்சலைச் சேர்',
    'On the code screen you can ask for the code to go to a recovery address instead.' => 'குறியீட்டுத் திரையில், குறியீட்டை ஒரு மீட்பு முகவரிக்கு அனுப்பக் கேட்கலாம்.',
    '"Lost your password?" also accepts any of these addresses, and the link goes there.' => '"கடவுச்சொல் மறந்துவிட்டதா?" இந்த முகவரிகளில் எதையும் ஏற்கும், இணைப்பு அங்கே செல்லும்.',
    'After a password reset, the next code goes to your primary recovery address.' => 'கடவுச்சொல் மீட்டமைப்புக்குப் பிறகு, அடுத்த குறியீடு உங்கள் முதன்மை மீட்பு முகவரிக்குச் செல்லும்.',
    'Any change is told to your main mailbox and to the address that was replaced or removed.' => 'ஒவ்வொரு மாற்றமும் உங்கள் முதன்மை அஞ்சல்பெட்டிக்கும் மாற்றப்பட்ட அல்லது நீக்கப்பட்ட முகவரிக்கும் தெரிவிக்கப்படும்.',
    'From recent messages (%s)' => 'சமீபத்திய செய்திகளிலிருந்து (%s)',
    'Country or Global…' => 'நாடு அல்லது உலகளாவிய…',
    'Country or Global' => 'நாடு அல்லது உலகளாவிய',
    'Provider' => 'வழங்குநர்',
    'Preferably a mailbox on the domain of this site, @%1$s. Country → provider fills SMTP server, encryption and port automatically (shown in the note and editable below). If yours is missing, type the server by hand (often mail.%2$s) and confirm it with them.' => 'இந்தத் தளத்தின் டொமைனில் உள்ள அஞ்சல்பெட்டி சிறந்தது, @%1$s. நாடு → வழங்குநர் தேர்வு SMTP சேவையகம், மறையாக்கம், போர்ட் ஆகியவற்றைத் தானாக நிரப்பும் (குறிப்பில் காட்டப்படும், கீழே திருத்தலாம்). உங்களுடையது இல்லையென்றால், சேவையகத்தைக் கையால் உள்ளிட்டு (பெரும்பாலும் mail.%2$s) அவர்களிடம் உறுதிசெய்யவும்.',
    'Filled when you choose a provider. You can still edit it. Your provider gives it to you.' => 'வழங்குநரைத் தேர்ந்தெடுத்தால் நிரப்பப்படும். இன்னும் திருத்தலாம். உங்கள் வழங்குநர் இதைத் தருவார்.',
    'Filled with the provider preset. Some providers use other values — check the note and change them here if needed.' => 'வழங்குநரின் முன்னமைவால் நிரப்பப்பட்டது. சில வழங்குநர்கள் வேறு மதிப்புகளைப் பயன்படுத்துவர் — குறிப்பைப் பார்த்துத் தேவைப்பட்டால் இங்கே மாற்றவும்.',
    'Template host' => 'வார்ப்புரு ஹோஸ்ட்',
    'Check before you trust this preset' => 'இந்த முன்னமைவை நம்பும் முன் சரிபார்க்கவும்',
    'Connection preset' => 'இணைப்பு முன்னமைவு',
    'Encryption' => 'மறையாக்கம்',
    'Fill this from your hosting panel (assigned per account).' => 'உங்கள் ஹோஸ்டிங் பேனலிலிருந்து நிரப்பவும் (ஒவ்வொரு கணக்குக்கும் தனியாக ஒதுக்கப்படும்).',
    'Choosing a provider fills SMTP server, encryption and port below automatically. You can still edit them.' => 'வழங்குநரைத் தேர்ந்தெடுத்தால் கீழே SMTP சேவையகம், மறையாக்கம், போர்ட் தானாக நிரப்பப்படும். இன்னும் திருத்தலாம்.',
    'Recent messages cleared.' => 'சமீபத்திய செய்திகள் அழிக்கப்பட்டன.',
    '%s is blocked. Messages and sign-ups from that address are held or refused.' => '%s தடுக்கப்பட்டது. அந்த முகவரியிலிருந்து வரும் செய்திகளும் பதிவுகளும் நிறுத்தி வைக்கப்படும் அல்லது மறுக்கப்படும்.',
    'Nothing was blocked: the address is not valid, belongs to an administrator, or is your own.' => 'எதுவும் தடுக்கப்படவில்லை: முகவரி செல்லாதது, ஒரு நிர்வாகியுடையது, அல்லது உங்களுடையது.',
    'Block this address?' => 'இந்த முகவரியைத் தடுக்கவா?',
    '"Accepted" means the server took it, not that it reached the inbox. With PHP mail(), not even that. Message bodies are never stored. You can clear the list, or block an address that confirmed a form or sign-up.' => '"ஏற்கப்பட்டது" என்றால் சேவையகம் அதைப் பெற்றது, உள்வரும் பெட்டியை அடைந்தது என்பதல்ல. PHP mail()-உடன் அதுகூடத் தெரியாது. செய்தி உள்ளடக்கம் ஒருபோதும் சேமிக்கப்படாது. பட்டியலை அழிக்கலாம், அல்லது படிவம் அல்லது பதிவை உறுதிசெய்த முகவரியைத் தடுக்கலாம்.',
    'Clear all recent messages from this list? This cannot be undone.' => 'இந்தப் பட்டியலின் சமீபத்திய செய்திகள் அனைத்தையும் அழிக்கவா? இதைத் திரும்பப் பெற முடியாது.',
    'Global' => 'உலகளாவிய',
    'BD — Bangladesh' => 'BD — வங்காளதேசம்',
    'BR — Brazil' => 'BR — பிரேசில்',
    'CN — China' => 'CN — சீனா',
    'CO — Colombia' => 'CO — கொலம்பியா',
    'DE — Germany' => 'DE — ஜெர்மனி',
    'ES — Spain' => 'ES — ஸ்பெயின்',
    'ET — Ethiopia' => 'ET — எத்தியோப்பியா',
    'FR — France' => 'FR — பிரான்ஸ்',
    'HK — Hong Kong' => 'HK — ஹாங்காங்',
    'ID — Indonesia' => 'ID — இந்தோனேசியா',
    'IN — India' => 'IN — இந்தியா',
    'IQ — Iraq' => 'IQ — ஈராக்',
    'MX — Mexico' => 'MX — மெக்சிகோ',
    'NL — Netherlands' => 'NL — நெதர்லாந்து',
    'PL — Poland' => 'PL — போலந்து',
    'RU — Russia' => 'RU — ரஷ்யா',
    'TR — Türkiye' => 'TR — துருக்கி',
    'UK — United Kingdom' => 'UK — ஐக்கிய இராச்சியம்',
    'US — United States' => 'US — அமெரிக்கா',
    'VN — Vietnam' => 'VN — வியட்நாம்',
    'This provider uses a host that depends on your domain or the server assigned to your account. Fill the outgoing server as shown, or copy it from your hosting panel.' => 'இந்த வழங்குநர் உங்கள் டொமைன் அல்லது உங்கள் கணக்குக்கு ஒதுக்கப்பட்ட சேவையகத்தைப் பொறுத்த ஹோஸ்டைப் பயன்படுத்துகிறார். வெளிச்செல்லும் சேவையகத்தைக் காட்டியபடி நிரப்பவும், அல்லது உங்கள் ஹோஸ்டிங் பேனலிலிருந்து நகலெடுக்கவும்.',
    'Titan Email (smtp.titan.email, 465 SSL) is used by several hostings (Bluehost Professional Email, HostGator Brasil Titan, BigRock Titan, IraqHosting business mail…).' => 'Titan Email (smtp.titan.email, 465 SSL) பல ஹோஸ்டிங் நிறுவனங்களால் பயன்படுத்தப்படுகிறது (Bluehost Professional Email, HostGator Brasil Titan, BigRock Titan, IraqHosting வணிக மின்னஞ்சல்…).',
    'Also documented: port 587 with STARTTLS/TLS if 465 fails.' => 'ஆவணப்படுத்தப்பட்டது: 465 தோல்வியுற்றால் STARTTLS/TLS உடன் போர்ட் 587.',
    'Use the normal mailbox password. SSL on 465 is the usual setting.' => 'அஞ்சல்பெட்டியின் வழக்கமான கடவுச்சொல்லைப் பயன்படுத்தவும். 465-இல் SSL வழக்கமான அமைப்பு.',
    'IONOS hosts differ by country: .es, .de and .com are not interchangeable.' => 'IONOS ஹோஸ்ட்கள் நாட்டுக்கு நாடு வேறுபடும்: .es, .de, .com ஒன்றுக்குப் பதில் மற்றொன்றைப் பயன்படுத்த முடியாது.',
    'Official alternative host: smtp.mail.ovh.net (same 465 SSL).' => 'அதிகாரப்பூர்வ மாற்று ஹோஸ்ட்: smtp.mail.ovh.net (அதே 465 SSL).',
    '123 Reg Professional Email currently uses the same GoDaddy Titan host (smtpout.secureserver.net).' => '123 Reg Professional Email தற்போது GoDaddy-யின் அதே Titan ஹோஸ்டைப் பயன்படுத்துகிறது (smtpout.secureserver.net).',
    'Spanish hosting mail. Prefer a mailbox on this site’s domain.' => 'ஸ்பானிஷ் ஹோஸ்டிங் மின்னஞ்சல். இந்தத் தளத்தின் டொமைனில் உள்ள அஞ்சல்பெட்டி சிறந்தது.',
    'EU datacentre. With two-step verification, create an app password.' => 'EU தரவு மையம். இரண்டு-படி சரிபார்ப்புடன் ஒரு ஆப் கடவுச்சொல்லை உருவாக்கவும்.',
    'Authenticated SMTP must be enabled for the mailbox in the Microsoft 365 admin centre.' => 'Microsoft 365 நிர்வாக மையத்தில் அஞ்சல்பெட்டிக்கு அங்கீகரிக்கப்பட்ட SMTP இயக்கப்பட்டிருக்க வேண்டும்.',
    'Requires an app password (or SMTP relay for Workspace). Normal Google password will not work with 2FA.' => 'ஆப் கடவுச்சொல் தேவை (அல்லது Workspace-க்கு SMTP ரிலே). 2FA உடன் வழக்கமான Google கடவுச்சொல் வேலை செய்யாது.',
    'Transactional relay: use the SMTP login and key from Brevo, not the mailbox password.' => 'பரிவர்த்தனை ரிலே: அஞ்சல்பெட்டியின் கடவுச்சொல் அல்ல, Brevo-வின் SMTP உள்நுழைவு மற்றும் விசையைப் பயன்படுத்தவும்.',
    'Relay for a verified domain in Mailgun.' => 'Mailgun-இல் சரிபார்க்கப்பட்ட டொமைனுக்கான ரிலே.',
    'Username must be the literal word “apikey”; password is the API key.' => 'பயனர்பெயர் எழுத்துக்கு எழுத்து "apikey" என்ற சொல்லாக இருக்க வேண்டும்; கடவுச்சொல் API விசை.',
    'Username and password are both the Server API Token.' => 'பயனர்பெயர், கடவுச்சொல் இரண்டுமே Server API Token.',
    'API key as username, secret key as password.' => 'பயனர்பெயராக API விசை, கடவுச்சொல்லாக இரகசிய விசை.',
    'Region Ireland (eu-west-1). Create SMTP credentials in SES; do not use your AWS console password.' => 'அயர்லாந்து பிராந்தியம் (eu-west-1). SES-இல் SMTP சான்றுகளை உருவாக்கவும்; உங்கள் AWS கன்சோல் கடவுச்சொல்லைப் பயன்படுத்த வேண்டாம்.',
    'Personal Microsoft account. Prefer a mailbox on this site’s domain for deliverability.' => 'தனிப்பட்ட Microsoft கணக்கு. செய்திகள் சென்றடைய இந்தத் தளத்தின் டொமைனில் உள்ள அஞ்சல்பெட்டி சிறந்தது.',
    'Requires an app password. Not ideal as the site’s main sender.' => 'ஆப் கடவுச்சொல் தேவை. தளத்தின் முதன்மை அனுப்புநராக ஏற்றதல்ல.',
    'Requires an app-specific password from appleid.apple.com.' => 'appleid.apple.com-இலிருந்து ஆப்-குறிப்பிட்ட கடவுச்சொல் தேவை.',
    'Different product from GoDaddy Professional Email (Titan). Authenticated SMTP must be allowed in Microsoft 365.' => 'GoDaddy Professional Email (Titan) இலிருந்து வேறுபட்ட தயாரிப்பு. Microsoft 365-இல் அங்கீகரிக்கப்பட்ட SMTP அனுமதிக்கப்பட வேண்டும்.',
    'In the EU, Bluehost documents smtp0101.titan.email as a variant.' => 'EU-வில் Bluehost smtp0101.titan.email-ஐ ஒரு மாறுபாடாக ஆவணப்படுத்துகிறது.',
    'Host is often {server}.hostgator.com or mail.{domain}. Copy it from HostGator.' => 'ஹோஸ்ட் பெரும்பாலும் {server}.hostgator.com அல்லது mail.{domain}. HostGator-இலிருந்து நகலெடுக்கவும்.',
    'Reliable sources agree, but no direct official URL was found. You must enable IMAP/SMTP and use a 16-character authorization code (normal password fails).' => 'நம்பகமான ஆதாரங்கள் ஒத்துப்போகின்றன, ஆனால் நேரடி அதிகாரப்பூர்வ URL கிடைக்கவில்லை. IMAP/SMTP-ஐ இயக்கி 16-எழுத்து அங்கீகாரக் குறியீட்டைப் பயன்படுத்த வேண்டும் (வழக்கமான கடவுச்சொல் தோல்வியடையும்).',
    'Reliable sources agree; no direct official URL. Safe preset is 465 SSL only. Enable IMAP/SMTP and use an authorization code.' => 'நம்பகமான ஆதாரங்கள் ஒத்துப்போகின்றன; நேரடி அதிகாரப்பூர்வ URL இல்லை. பாதுகாப்பான முன்னமைவு 465 SSL மட்டுமே. IMAP/SMTP-ஐ இயக்கி அங்கீகாரக் குறியீட்டைப் பயன்படுத்தவும்.',
    'Official docs: ports 80 and 587 are not available for SMTP. Use 465 SSL only. Enable third-party clients / client password.' => 'அதிகாரப்பூர்வ ஆவணம்: போர்ட்கள் 80, 587 SMTP-க்குக் கிடைக்காது. 465 SSL மட்டும் பயன்படுத்தவும். மூன்றாம் தரப்புக் கிளையன்ட்கள் / கிளையன்ட் கடவுச்சொல்லை இயக்கவும்.',
    'Official docs: ports 80 and 587 are not available for SMTP. Use 465 SSL only.' => 'அதிகாரப்பூர்வ ஆவணம்: போர்ட்கள் 80, 587 SMTP-க்குக் கிடைக்காது. 465 SSL மட்டும் பயன்படுத்தவும்.',
    'Reliable sources agree; no direct official URL. App password required if Secure Login is on.' => 'நம்பகமான ஆதாரங்கள் ஒத்துப்போகின்றன; நேரடி அதிகாரப்பூர்வ URL இல்லை. பாதுகாப்பான உள்நுழைவு இயக்கத்தில் இருந்தால் ஆப் கடவுச்சொல் தேவை.',
    'Same Hostinger SMTP worldwide. Use the mailbox password.' => 'உலகம் முழுவதும் அதே Hostinger SMTP. அஞ்சல்பெட்டி கடவுச்சொல்லைப் பயன்படுத்தவும்.',
    'Mailhostbox product (not Titan). Confirm the regional host in the BigRock panel if login fails.' => 'Mailhostbox தயாரிப்பு (Titan அல்ல). உள்நுழைவு தோல்வியுற்றால் BigRock பேனலில் பிராந்திய ஹோஸ்டை உறுதிசெய்யவும்.',
    'Their WP-Mail-SMTP guide uses mail.{domain}.com.br style hosts and prefers 587/STARTTLS.' => 'அவர்களின் WP-Mail-SMTP வழிகாட்டி mail.{domain}.com.br போன்ற ஹோஸ்ட்களைப் பயன்படுத்துகிறது; 587/STARTTLS-ஐ விரும்புகிறது.',
    'Mailbox product on Locaweb. Prefer a mailbox on this site’s domain.' => 'Locaweb அஞ்சல்பெட்டி தயாரிப்பு. இந்தத் தளத்தின் டொமைனில் உள்ள அஞ்சல்பெட்டி சிறந்தது.',
    'Transactional SMTP product (smtplw.com.br), separate from Email Locaweb.' => 'பரிவர்த்தனை SMTP தயாரிப்பு (smtplw.com.br), Email Locaweb-இலிருந்து தனி.',
    'Same host as GoDaddy Titan. Old smtp.123-reg.co.uk is not in current official docs.' => 'GoDaddy Titan-இன் அதே ஹோஸ்ட். பழைய smtp.123-reg.co.uk தற்போதைய அதிகாரப்பூர்வ ஆவணங்களில் இல்லை.',
    'Their guide uses 587/STARTTLS for hosting mail.' => 'அவர்களின் வழிகாட்டி ஹோஸ்டிங் மின்னஞ்சலுக்கு 587/STARTTLS பயன்படுத்துகிறது.',
    'Host is the assigned server (e.g. chv4-24911.azdigi.com). Copy it from AZDIGI.' => 'ஹோஸ்ட் என்பது ஒதுக்கப்பட்ட சேவையகம் (எ.கா. chv4-24911.azdigi.com). AZDIGI-இலிருந்து நகலெடுக்கவும்.',
    'Pro Mail host (not the same as cPanel hosting mail).' => 'Pro Mail ஹோஸ்ட் (cPanel ஹோஸ்டிங் மின்னஞ்சல் போன்றது அல்ல).',
    'Host looks like proXX.emailserver.vn or svXXdXXX.emailserver.vn — copy from Mat Bao.' => 'ஹோஸ்ட் proXX.emailserver.vn அல்லது svXXdXXX.emailserver.vn போல இருக்கும் — Mat Bao-இலிருந்து நகலெடுக்கவும்.',
    'Host looks like mailXX.maychuemail.com — assigned per account.' => 'ஹோஸ்ட் mailXX.maychuemail.com போல இருக்கும் — ஒவ்வொரு கணக்குக்கும் தனியாக ஒதுக்கப்படும்.',
    'Linux hosting mail. Confirm in the reg.ru panel if your plan uses another host.' => 'Linux ஹோஸ்டிங் மின்னஞ்சல். உங்கள் திட்டம் வேறு ஹோஸ்டைப் பயன்படுத்தினால் reg.ru பேனலில் உறுதிசெய்யவும்.',
    'Documented limit: 30 messages/min and 1500/hour over SMTP.' => 'ஆவணப்படுத்திய வரம்பு: SMTP வழியாக நிமிடத்துக்கு 30, மணிக்கு 1500 செய்திகள்.',
    'Shared Timeweb SMTP for hosting mailboxes.' => 'ஹோஸ்டிங் அஞ்சல்பெட்டிகளுக்கான பகிரப்பட்ட Timeweb SMTP.',
    'Enable IMAP and use an app password.' => 'IMAP-ஐ இயக்கி ஆப் கடவுச்சொல்லைப் பயன்படுத்தவும்.',
    'Their WordPress guide documents 587 without encryption for hosting mail. Corporate mail is a different product. Prefer STARTTLS if the server allows it.' => 'அவர்களின் WordPress வழிகாட்டி ஹோஸ்டிங் மின்னஞ்சலுக்கு மறையாக்கம் இல்லாத 587-ஐ ஆவணப்படுத்துகிறது. நிறுவன மின்னஞ்சல் வேறு தயாரிப்பு. சேவையகம் அனுமதித்தால் STARTTLS-ஐ விரும்பவும்.',
    'Corporate product (mail.kurumsaleposta.com), not hosting mail.' => 'நிறுவனத் தயாரிப்பு (mail.kurumsaleposta.com), ஹோஸ்டிங் மின்னஞ்சல் அல்ல.',
    'Encryption not stated clearly in the source; try STARTTLS on 587 first.' => 'ஆதாரத்தில் மறையாக்கம் தெளிவாகக் குறிப்பிடப்படவில்லை; முதலில் 587-இல் STARTTLS முயலவும்.',
    'Mailmatik outgoing host (giden.mailmatik.com).' => 'Mailmatik வெளிச்செல்லும் ஹோஸ்ட் (giden.mailmatik.com).',
    'OX App Suite enterprise mail (smtp.us.appsuite.cloud), not hosting mail.' => 'OX App Suite நிறுவன மின்னஞ்சல் (smtp.us.appsuite.cloud), ஹோஸ்டிங் மின்னஞ்சல் அல்ல.',
    'Their guide prefers 587/STARTTLS.' => 'அவர்களின் வழிகாட்டி 587/STARTTLS-ஐ விரும்புகிறது.',
    'SSL required; TLS 1.2+. 465 also documented — switch encryption/port below if 587 fails.' => 'SSL கட்டாயம்; TLS 1.2+. 465-உம் ஆவணப்படுத்தப்பட்டுள்ளது — 587 தோல்வியுற்றால் கீழே மறையாக்கம்/போர்ட்டை மாற்றவும்.',
    'Their docs mark STARTTLS as unused: prefer 465 SSL. 587 is without SSL.' => 'அவர்களின் ஆவணம் STARTTLS-ஐப் பயன்படுத்தப்படாதது எனக் குறிக்கிறது: 465 SSL-ஐ விரும்பவும். 587 SSL இல்லாதது.',
    'Only 587/TLS is documented. On their VPS, ports 25 and 465 are blocked by default — do not force 465.' => '587/TLS மட்டுமே ஆவணப்படுத்தப்பட்டுள்ளது. அவர்களின் VPS-இல் போர்ட்கள் 25, 465 இயல்பாகத் தடுக்கப்பட்டவை — 465-ஐ வற்புறுத்த வேண்டாம்.',
    'Same Alibaba rule: no port 587 for SMTP; use 465 SSL.' => 'அதே Alibaba விதி: SMTP-க்கு போர்ட் 587 இல்லை; 465 SSL பயன்படுத்தவும்.',
    'Official docs recommend 587/STARTTLS at the top and 465/SSL in detailed steps — both work. Prefer 587 first; you can change encryption/port below.' => 'அதிகாரப்பூர்வ ஆவணம் மேலே 587/STARTTLS-ஐயும் விரிவான படிகளில் 465/SSL-ஐயும் பரிந்துரைக்கிறது — இரண்டும் வேலை செய்யும். முதலில் 587 முயலவும்; கீழே மறையாக்கம்/போர்ட்டை மாற்றலாம்.',
    'Host pattern: yourdomain.correoseguro.dinaserver.com.' => 'ஹோஸ்ட் வடிவம்: yourdomain.correoseguro.dinaserver.com.',
    'Current official page uses authsmtp.securemail.pro (not the older smtp-es.securemail.pro).' => 'தற்போதைய அதிகாரப்பூர்வப் பக்கம் authsmtp.securemail.pro-ஐப் பயன்படுத்துகிறது (பழைய smtp-es.securemail.pro அல்ல).',
    'Or the cPanel hostname assigned to your account.' => 'அல்லது உங்கள் கணக்குக்கு ஒதுக்கப்பட்ட cPanel ஹோஸ்ட்பெயர்.',
    'Not interchangeable with smtp.ionos.de or smtp.ionos.com.' => 'smtp.ionos.de அல்லது smtp.ionos.com-க்குப் பதிலாகப் பயன்படுத்த முடியாது.',
    'Strato mailbox SMTP. Prefer a mailbox on this site’s domain.' => 'Strato அஞ்சல்பெட்டி SMTP. இந்தத் தளத்தின் டொமைனில் உள்ள அஞ்சல்பெட்டி சிறந்தது.',
    'Not interchangeable with smtp.ionos.es or smtp.ionos.com.' => 'smtp.ionos.es அல்லது smtp.ionos.com-க்குப் பதிலாகப் பயன்படுத்த முடியாது.',
    'Or {server}.o2switch.net — copy from o2switch.' => 'அல்லது {server}.o2switch.net — o2switch-இலிருந்து நகலெடுக்கவும்.',
    'Host is the hosting server hostname for your account.' => 'ஹோஸ்ட் என்பது உங்கள் கணக்கின் ஹோஸ்டிங் சேவையக ஹோஸ்ட்பெயர்.',
    'TransIP mailbox SMTP.' => 'TransIP அஞ்சல்பெட்டி SMTP.',
    'Exception: Hostnet’s standard is 587/STARTTLS, not 465/SSL. Do not force 465. Guide also mentions mailout.hostnet.nl.' => 'விதிவிலக்கு: Hostnet-இன் தரநிலை 587/STARTTLS, 465/SSL அல்ல. 465-ஐ வற்புறுத்த வேண்டாம். வழிகாட்டி mailout.hostnet.nl-ஐயும் குறிப்பிடுகிறது.',
    'Host looks like serwerNNNNNN.home.pl — assigned per account.' => 'ஹோஸ்ட் serwerNNNNNN.home.pl போல இருக்கும் — ஒவ்வொரு கணக்குக்கும் தனியாக ஒதுக்கப்படும்.',
    'Host looks like serverNNNNNN.nazwa.pl — assigned per account.' => 'ஹோஸ்ட் serverNNNNNN.nazwa.pl போல இருக்கும் — ஒவ்வொரு கணக்குக்கும் தனியாக ஒதுக்கப்படும்.',
    'mi.com.co documents 587/STARTTLS as the standard outgoing setting.' => 'mi.com.co 587/STARTTLS-ஐ நிலையான வெளிச்செல்லும் அமைப்பாக ஆவணப்படுத்துகிறது.',
    'Write the abuse address of the network that owns this IP address. Your hosting provider or the regional internet registry of the address can tell you which one it is.' => 'இந்த IP முகவரிக்குச் சொந்தமான வலையமைப்பின் abuse முகவரியை எழுதவும். உங்கள் ஹோஸ்டிங் வழங்குநர் அல்லது அந்த முகவரியின் பிராந்திய இணையப் பதிவகம் எது என்று சொல்ல முடியும்.',
    'Blocked addresses stay here until you unblock them or they expire. Clearing the list above does not remove them. Forms and sign-ups from a blocked address get the same “almost done” answer as everyone else, so they cannot tell.' => 'தடுக்கப்பட்ட முகவரிகள் நீங்கள் தடையை நீக்கும் வரை அல்லது காலாவதியாகும் வரை இங்கே இருக்கும். மேலே உள்ள பட்டியலை அழித்தால் அவை நீங்காது. தடுக்கப்பட்ட முகவரியிலிருந்து வரும் படிவங்களும் பதிவுகளும் எல்லோருக்கும் போலவே "கிட்டத்தட்ட முடிந்தது" பதிலைப் பெறும், எனவே அவர்களால் அறிய முடியாது.',
    'Full block list in Anti-bot shield →' => 'முழுத் தடைப் பட்டியல் பாட் எதிர்ப்புக் கேடயத்தில் →',
    'Registration is complete. Check your email for details!' => 'பதிவு முடிந்தது. உங்கள் மின்னஞ்சலைச் சரிபார்க்கவும்.',
    'One at a time: type an address, get its code and confirm it before going on to the next one.' => 'ஒவ்வொன்றாக: முகவரியை எழுதி, அதன் குறியீட்டைப் பெற்று, அடுத்ததற்குச் செல்லும் முன் உறுதிசெய்யவும்.',
    'Confirm the previous one first.' => 'முதலில் முந்தையதை உறுதிசெய்யவும்.',
    'Verified' => 'சரிபார்க்கப்பட்டது',
    'Free' => 'காலி',
    'PHP %s gets security updates' => 'PHP %s பாதுகாப்புப் புதுப்பிப்புகளைப் பெறுகிறது',
    'PHP %1$s gets security updates from php.net only until %2$s: choose a newer one in your hosting panel' => 'PHP %1$s php.net-இலிருந்து %2$s வரை மட்டுமே பாதுகாப்புப் புதுப்பிப்புகளைப் பெறும்: ஹோஸ்டிங் பேனலில் புதிய பதிப்பைத் தேர்ந்தெடுக்கவும்',
    'PHP %1$s has had no security updates from php.net since %2$s: choose a newer one in your hosting panel' => 'PHP %1$s %2$s முதல் php.net-இன் பாதுகாப்புப் புதுப்பிப்புகளைப் பெறவில்லை: ஹோஸ்டிங் பேனலில் புதிய பதிப்பைத் தேர்ந்தெடுக்கவும்',
    'Hide versions on public pages (WordPress, theme and plugins)' => 'பொதுப் பக்கங்களில் பதிப்புகளை மறை (WordPress, தீம், செருகுநிரல்கள்)',
    'Takes out the "generator" tags and turns "?ver=" of styles and scripts into a code that still changes on every update. It makes the site harder to list for robots looking for old versions; it does not fix anything: keep everything updated. readme.html and license.txt are sent by the web server without WordPress, so no plugin can refuse them: refuse them in the server.' => '"generator" குறிச்சொற்களை நீக்கி, ஸ்டைல்கள் மற்றும் ஸ்கிரிப்ட்களின் "?ver=" ஐ ஒவ்வொரு புதுப்பிப்பிலும் மாறிக்கொண்டே இருக்கும் குறியீடாக மாற்றுகிறது. பழைய பதிப்புகளைத் தேடும் ரோபோக்களுக்குத் தளத்தைப் பட்டியலிடுவது கடினமாகிறது; இது எதையும் சரிசெய்யாது: எல்லாவற்றையும் புதுப்பித்து வையுங்கள். readme.html, license.txt ஆகியவற்றை வலை சேவையகம் WordPress இல்லாமல் அனுப்புகிறது, எனவே எந்தச் செருகுநிரலும் அவற்றை மறுக்க முடியாது: சேவையகத்தில் மறுக்கவும்.',
    'content' => 'உள்ளடக்கம்',
    'search' => 'தேடல்',
    'user accounts' => 'பயனர் கணக்குகள்',
    '"Answer" is what the visitor got: 401 means the door was closed, 200 that the content was sent. Anonymous visitors always get 401 from /wp/v2/users/me, with or without Draco.' => '"பதில்" என்பது பார்வையாளர் பெற்றது: 401 என்றால் கதவு மூடப்பட்டிருந்தது, 200 என்றால் உள்ளடக்கம் அனுப்பப்பட்டது. அநாமதேயப் பார்வையாளர்கள் Draco இருந்தாலும் இல்லாவிட்டாலும் /wp/v2/users/me இலிருந்து எப்போதும் 401 பெறுவர்.',
    'Answer' => 'பதில்',
    'Publish /.well-known/security.txt (how to report a security problem)' => '/.well-known/security.txt ஐ வெளியிடு (பாதுகாப்புச் சிக்கலைத் தெரிவிக்கும் வழி)',
    'The standard file (RFC 9116) that tells whoever finds a weakness how to reach you. Draco renews its expiry date by itself.' => 'பலவீனத்தைக் கண்டறிபவருக்கு உங்களை எப்படித் தொடர்புகொள்வது எனச் சொல்லும் நிலையான கோப்பு (RFC 9116). அதன் காலாவதி தேதியை Draco தானே புதுப்பிக்கும்.',
    'Not possible here: the standard wants the file at the root of the domain, and this WordPress is in a folder.' => 'இங்கே முடியாது: தரநிலைப்படி கோப்பு டொமைனின் மூலத்தில் இருக்க வேண்டும், இந்த WordPress ஒரு கோப்புறையில் உள்ளது.',
    'Contact (e-mail or https:// address)' => 'தொடர்பு (மின்னஞ்சல் அல்லது https:// முகவரி)',
    'Policy page (optional, https://)' => 'கொள்கைப் பக்கம் (விருப்பம், https://)',
    'Not published yet: write a valid contact.' => 'இன்னும் வெளியிடப்படவில்லை: சரியான தொடர்பை எழுதுங்கள்.',
    'looking for configuration and keys' => 'அமைப்புகளையும் சாவிகளையும் தேடுகிறது',
    'looking for backup copies' => 'காப்புப் பிரதிகளைத் தேடுகிறது',
    'looking for logs' => 'பதிவுகளைத் தேடுகிறது',
    'looking for server information pages' => 'சேவையகத் தகவல் பக்கங்களைத் தேடுகிறது',
    'looking for database tools' => 'தரவுத்தளக் கருவிகளைத் தேடுகிறது',
    'looking for installers' => 'நிறுவிகளைத் தேடுகிறது',
    'trying a known exploit' => 'அறியப்பட்ட சுரண்டலை முயல்கிறது',
    'looking for a back door' => 'பின்வாசலைத் தேடுகிறது',
    'Kept for 90 days. "Evidence" downloads everything from that address for an abuse report. In log-only mode they appear as "Would block". Rows from an administrator\'s address (your own tests) are marked, cannot be reported and do not count in the summary.' => '90 நாட்கள் வைக்கப்படும். "சான்று" தவறான பயன்பாட்டு அறிக்கைக்காக அந்த முகவரியின் அனைத்தையும் பதிவிறக்கும். பதிவு மட்டும் முறையில் இவை "தடுத்திருக்கும்" எனக் காட்டப்படும். நிர்வாகியின் முகவரியிலிருந்து வரும் வரிகள் (உங்கள் சொந்தச் சோதனைகள்) குறிக்கப்படும், அவற்றைப் புகாரளிக்க முடியாது, சுருக்கத்தில் எண்ணப்படாது.',
